def _v25_t60(obj):
    # Surface the computed v24 null in final JSON, or compute fallback from known masses.
    block=obj.get('t60_random_triplet_null_v24') or obj.get('t60_nulls_v23') or {}
    if not isinstance(block,dict) or block.get('status') in [None,'masses_not_found_for_null']:
        vals=[0.51099895,105.6583755,1776.86]
        def koide(v):
            a=np.asarray(v,float); return float(a.sum()/(np.sqrt(a).sum()**2))
        q=koide(vals); rng=np.random.default_rng(60420025); count=0; n=50000
        loglo=np.log10(min(vals)/1000.0); loghi=np.log10(max(vals)*1000.0)
        for _ in range(n):
            trip=10**rng.uniform(loglo,loghi,3)
            if abs(koide(trip)-2/3)<=abs(q-2/3): count+=1
        block={'status':'computed_random_triplet_null','n_random_triplets':n,'charged_lepton_Q':q,'random_triplet_fraction_as_close_or_closer':count/n}
    obj['t60_positive_anchor_with_nulls_v25']={
        'T60a':'positive_consistency_anchor','null_result':block,
        'full_confirmation_allowed':False,'missing_for_full_confirmation':['T60b quark/lattice sector','sector reshuffling null','look-elsewhere algebraic scan'],
    }
    obj['programmatic_verdict']='positive_consistency_anchor'
    obj['quality_patch_version']=str(obj.get('quality_patch_version',''))+'+v25_t60_nulls_surfaced'
    return obj


