def _wrap_v25(test_id, ref):
    def runner(args):
        obj=ref(args)
        if test_id=='T31': obj=_v25_materials(obj)
        if test_id=='T32':
            obj['mat3b_uses_t31_grain_manifest_v25']={'status':'open_positive_path','rule':'decisive MAT3b only for grain_size_known or explicit nanocrystalline rows; broad materials are controls'}
            obj['programmatic_verdict']='null_broad_claim_open_narrow_claim'
            obj['quality_patch_version']=str(obj.get('quality_patch_version',''))+'+v25_mat3b_linked_manifest'
        if test_id=='T44': obj=_v25_t44(obj)
        if test_id=='T45': obj=_v25_t45(obj)
        if test_id=='T46': obj=_v25_t46(obj)
        if test_id=='T47': obj=_v25_t47(obj)
        if test_id=='T48': obj=_v25_t48b(obj)
        if test_id=='T53': obj=_v25_t53_model(obj,args)
        if test_id=='T60': obj=_v25_t60(obj)
        if test_id in {'T26','T27','T28','T29','T30'}: obj=_v25_fusion(obj,test_id)
        obj['positive_dashboard_fragment_v25']={'test_id':test_id,'verdict':obj.get('programmatic_verdict'), 'v25': {
            'materials':obj.get('materials_positive_score_v25'), 't44':obj.get('t44_nand_exact_parser_v25'), 't45':obj.get('t45_optical_interconnect_unit_extractor_v25'), 't47':obj.get('t47_exact_benchmark_targeting_v25'), 't53':obj.get('t53_organismalfitness_model_v25'), 't48b':obj.get('t48b_primary_descriptor_model_v25'), 't60':obj.get('t60_positive_anchor_with_nulls_v25'), 'fusion':obj.get('fusion_secondary_diagnostic_v25')}}
        return obj
    return runner

SPECIAL_RUNNERS.update({tid:_wrap_v25(tid,ref) for tid,ref in _run_v24_refs_for_v25.items() if ref is not None})


