def _v26_int(x, default=0):
    try:
        if x is None: return default
        if isinstance(x, bool): return int(x)
        if isinstance(x, (int, float)) and math.isfinite(float(x)): return int(x)
        m=re.search(r'-?\d+', str(x))
        return int(m.group(0)) if m else default
    except Exception:
        return default


def _v26_float(x, default=None):
    try:
        if x is None: return default
        if isinstance(x, (int,float)) and math.isfinite(float(x)): return float(x)
        m=re.search(r'[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?', str(x).replace(',',''))
        return float(m.group(0)) if m else default
    except Exception:
        return default


def _v26_deep_find(obj, keys, limit=100):
    out=[]
    keys=set(keys)
    def rec(x):
        if len(out)>=limit: return
        if isinstance(x, dict):
            for k,v in x.items():
                if k in keys: out.append(v)
                rec(v)
        elif isinstance(x, list):
            for v in x: rec(v)
    rec(obj); return out


def _v26_count_from_keys(obj, keys):
    vals=[]
    for k in keys:
        vals.extend(_v26_deep_find(obj,[k],limit=50))
    best=0
    for v in vals:
        if isinstance(v, (list,tuple,dict,set)): best=max(best,len(v))
        else: best=max(best,_v26_int(v,0))
    return best


def _v26_koide(vals):
    a=np.asarray(vals,float)
    return float(a.sum()/(np.sqrt(a).sum()**2))


def _v26_t60_confirm(obj):
    # Always surface computed random-triplet null plus protocol for sector reshuffling/look-elsewhere.
    masses=[0.51099895,105.6583755,1776.86]
    q=_v26_koide(masses); dev=abs(q-2/3)
    rng=np.random.default_rng(6062026)
    n=100000; count=0
    loglo=np.log10(min(masses)/1000.0); loghi=np.log10(max(masses)*1000.0)
    for _ in range(n):
        trip=10**rng.uniform(loglo, loghi, 3)
        if abs(_v26_koide(trip)-2/3) <= dev: count += 1
    # deterministic simple sector reshuffling control: known SM-ish masses are not complete enough here, so emit required machine gate.
    obj['t60_confirm_strength_v26']={
        'T60a_status':'confirmed_consistency_anchor',
        'charged_lepton_Q':q,
        'deviation_from_2_over_3':dev,
        'random_triplet_null':{'n_random_triplets':n,'fraction_as_close_or_closer':count/n,'log_uniform_mass_range':'charged lepton range expanded by 1e3'},
        'sector_reshuffling_null':'required_for_full_T60; implemented gate expects charged-lepton/quark/lattice parsed sectors',
        'look_elsewhere_scan':'required_for_full_T60; algebraic relation registry must pass before CCDR-sector confirmation',
        'T60b_quark_lattice_status':'data_limited_until_FLAG_PDG_uncertainty_rows_parse',
        'full_T60_confirmation_allowed':False,
        'confirm_language_allowed':'T60a consistency anchor only',
    }
    obj['programmatic_verdict']='positive_consistency_anchor'
    obj['quality_patch_version']=str(obj.get('quality_patch_version',''))+'+v26_t60_confirm_nulls'
    return obj


def _v26_materials_confirm(obj, test_id):
    # Confirm-aware scorer for T31 and T32, consuming all previous key names and enforcing row thresholds.
    prev=obj.get('materials_positive_score_v25') or obj.get('materials_positive_score_v24') or obj.get('materials_positive_score_v23') or obj.get('materials_positive_score_v20') or {}
    grain=obj.get('grain_or_nano_known') or obj.get('grain_or_nano_subset') or {}
    fits=max(_v26_int(prev.get('grain_or_nano_usable_fits')), _v26_int(prev.get('usable_fits')), _v26_int(grain.get('usable_fits')), _v26_count_from_keys(obj,['grain_or_nano_usable_fits']))
    frac=_v26_float(prev.get('fraction_ccdr_better_by_aic2'), None)
    if frac is None: frac=_v26_float(grain.get('fraction_ccdr_better_by_aic2'), None)
    daic=_v26_float(prev.get('median_delta_aic_ccdr_minus_power'), None)
    if daic is None: daic=_v26_float(grain.get('median_delta_aic_ccdr_minus_power'), None)
    decisive=max(_v26_int(prev.get('decisive_microstructure_rows')), _v26_count_from_keys(obj,['decisive_microstructure_rows','explicit_grain_size_rows','explicit_nanocrystalline_rows']))
    source_rows=max(_v26_int(prev.get('source_matched_or_manifest_rows')), _v26_count_from_keys(obj,['source_matched_rows','microstructure_manifest_rows']))
    score=0; reasons=[]
    if frac is not None and frac>0.5: score+=2; reasons.append('grain/nano CCDR-better fraction > 0.5')
    if daic is not None and daic<0: score+=2; reasons.append('grain/nano median ΔAIC favors CCDR')
    if fits>=10: score+=2; reasons.append('grain/nano usable fits >=10')
    elif fits>=5: score+=1; reasons.append('grain/nano usable fits >=5 but underpowered')
    if decisive>=10: score+=2; reasons.append('decisive microstructure rows >=10')
    elif decisive>=3: score+=1; reasons.append('some decisive microstructure rows but underpowered')
    status='not_positive_yet'
    confirm_allowed=False
    if score>=8 and fits>=10 and decisive>=10:
        status='confirm_candidate_requires_jackknife'
    elif score>=5:
        status='strong_positive_candidate_near_confirmation'
    elif score>=3:
        status='positive_lead_underpowered'
    obj['materials_confirm_path_v26']={
        'test_id':test_id,'score':score,'status':status,'confirm_allowed_now':confirm_allowed,
        'grain_or_nano_usable_fits':fits,'fraction_ccdr_better_by_aic2':frac,'median_delta_aic_ccdr_minus_power':daic,
        'decisive_microstructure_rows':decisive,'source_matched_rows':source_rows,'reasons':reasons,
        'confirm_threshold':'usable grain/nano fits >=10-20; decisive rows >=10; fraction CCDR-better>0.5; median ΔAIC<0; source/material-family and temperature-window jackknife stable',
        'implementation_added':'reference/supplement sentence-mining route for grain size/crystallite/nanocrystalline/SEM/TEM/nm/μm; T32 MAT3b consumes same manifest; broad materials are controls',
        'next_artifact':'data/generated/grain_size_known_manifest_v26.csv',
    }
    if test_id=='T31' and score>=5: obj['programmatic_verdict']='positive_physical_lead'
    if test_id=='T32':
        obj['programmatic_verdict']='null_broad_claim_open_narrow_claim'
        obj['mat3b_confirm_gate_v26']={'broad_MAT3a':'null_pressure_control','MAT3b':'open_confirm_path_only_on_measured_grain_or_nanocrystalline_rows','uses_T31_manifest':True}
    obj['quality_patch_version']=str(obj.get('quality_patch_version',''))+'+v26_materials_confirm_gate'
    return obj


