def _v26_t46_optimizer(obj):
    # Deterministic optimizer-style proxy: still not evidence, but gives CI-ready structure.
    rng=np.random.default_rng(460026)
    families={
        'cdt_hybrid_optimized':(0.915,0.018),
        'matched_spatially_coupled_LDPC':(0.920,0.014),
        'matched_protograph_LDPC':(0.902,0.018),
        'matched_interleaved_burst_baseline':(0.895,0.020),
    }
    sims={}
    for name,(mu,sd) in families.items():
        vals=np.clip(rng.normal(mu,sd,500),0,1)
        sims[name]={'n_seeds':500,'mean_correctable_fraction':float(vals.mean()),'ci95':[float(np.quantile(vals,0.025)),float(np.quantile(vals,0.975))]}
    best_non=max([v['mean_correctable_fraction'] for k,v in sims.items() if k!='cdt_hybrid_optimized'])
    cdt=sims['cdt_hybrid_optimized']['mean_correctable_fraction']
    obj['t46b_confirm_optimizer_v26']={
        'scope':'engineering search only; not CCDR physics evidence',
        'T46a':'current strong-baseline benchmark remains null',
        'T46b_status':'open_optimizer_not_confirmed' if cdt<=best_non else 'engineering_confirm_candidate_requires_real_decoder',
        'simulated_optimizer_proxy':sims,
        'beats_best_non_CDT_baseline':bool(cdt>best_non),
        'required_for_confirm':['real graph optimizer','BP/min-sum decoder','matched rate/check density','bootstrap CI excludes zero','not one-seed driven'],
    }
    obj['programmatic_verdict']='null_current_benchmark_design_search_ready'
    obj['quality_patch_version']=str(obj.get('quality_patch_version',''))+'+v26_t46b_optimizer'
    return obj


