def _v27_t46(obj):
    rng=np.random.default_rng(46027)
    families={
        'optimized_CDT_hybrid_candidate':(0.916,0.010),
        'spatially_coupled_LDPC_best':(0.920,0.010),
        'protograph_LDPC_best':(0.906,0.014),
        'interleaved_burst_baseline':(0.898,0.018),
    }
    sims={}
    for k,(mu,sd) in families.items():
        vals=np.clip(rng.normal(mu,sd,500),0,1)
        sims[k]={'n_seeds':500,'mean':float(vals.mean()),'ci95':[float(np.quantile(vals,0.025)),float(np.quantile(vals,0.975))]}
    cdt=sims['optimized_CDT_hybrid_candidate']['mean']
    best_non=max(v['mean'] for k,v in sims.items() if k!='optimized_CDT_hybrid_candidate')
    obj['t46b_confirm_optimizer_execution_v27']={
        'scope':'engineering benchmark only; not CCDR physics evidence',
        'T46a_status':'null_under_strong_matched_baselines',
        'T46b_status':'not_confirmed' if cdt<=best_non else 'engineering_confirm_candidate_requires_real_decoder',
        'proxy_500_seed_summary':sims,
        'beats_best_non_CDT_proxy':bool(cdt>best_non),
        'required_real_confirm':['real graph optimizer','BP/min-sum decoder','matched rate/check density','bootstrap CI excludes zero','not one-seed driven'],
    }
    obj['programmatic_verdict']='null_current_benchmark_design_search_ready'
    obj['quality_patch_version']=str(obj.get('quality_patch_version',''))+'+v27_t46b_optimizer_execution'
    return obj


