def _v37_norm_text(x: Any) -> str:
    return re.sub(r"\s+", " ", str(x or "").strip())


def _v37_sigmoid_descriptor_from_text(fam: str, cell: str, extra: str = "") -> Dict[str, Any]:
    txt = f"{fam} {cell} {extra}".lower()
    # Descriptor proxies are not claimed physical truth; they are reproducible public-row proxies.
    crystalline = 0.0
    if re.search(r"\bmono|single[- ]?crystal|crystalline|c[- ]?si|gaas|inp|ge|iii[- ]?v|wafer", txt):
        crystalline += 1.0
    if re.search(r"poly|thin[- ]?film|amorph|organic|dye|quantum dot|perovskite", txt):
        crystalline -= 0.35
    direct_gap = 1.0 if re.search(r"gaas|inp|cdte|cigs|perovskite|iii[- ]?v|multijunction|tandem", txt) else 0.0
    defect_proxy = 1.0 if re.search(r"organic|dye|quantum dot|amorph|poly|thin[- ]?film", txt) else 0.0
    tandem = bool(re.search(r"tandem|multi[- ]?junction|junction|perovskite/silicon|two[- ]?terminal|four[- ]?terminal", txt))
    concentrator = bool(re.search(r"concentrator|concentration|suns|sun\(|\d+\s*x\b|\bx\s*sun", txt))
    return {
        "crystallinity_proxy_v37": float(crystalline),
        "direct_gap_proxy_v37": float(direct_gap),
        "defect_proxy_v37": float(defect_proxy),
        "tandem_v37": tandem,
        "concentrator_v37": concentrator,
    }


def _v37_ols_fit(y: np.ndarray, X: np.ndarray) -> Dict[str, Any]:
    n = int(len(y)); k = int(X.shape[1]) if X.ndim == 2 else 0
    if n <= k or k == 0:
        return {"ok": False, "reason": "n_le_k", "n": n, "k": k}
    beta, *_ = np.linalg.lstsq(X, y, rcond=None)
    resid = y - X @ beta
    rss = float(np.sum(resid ** 2))
    sigma2 = rss / max(1, n - k)
    try:
        cov = sigma2 * np.linalg.pinv(X.T @ X)
        se = np.sqrt(np.maximum(np.diag(cov), 1e-18))
        tvals = beta / se
        # Normal approximation; avoids scipy dependency.
        pvals = [float(2.0 * (1.0 - 0.5 * (1.0 + math.erf(abs(float(t)) / math.sqrt(2.0))))) for t in tvals]
    except Exception:
        se = np.full(k, np.nan); tvals = np.full(k, np.nan); pvals = [None] * k
    aic = n * math.log(max(rss / max(n, 1), 1e-12)) + 2 * k
    bic = n * math.log(max(rss / max(n, 1), 1e-12)) + math.log(max(n, 2)) * k
    return {"ok": True, "n": n, "k": k, "beta": [float(x) for x in beta], "se": [float(x) for x in se], "t": [float(x) for x in tvals], "p": pvals, "rss": rss, "aic": float(aic), "bic": float(bic)}


def _v37_bh_flags(pvals: Sequence[Optional[float]], alpha: float = 0.10) -> List[bool]:
    vals = [(i, float(p)) for i, p in enumerate(pvals) if p is not None and math.isfinite(float(p))]
    vals.sort(key=lambda x: x[1])
    flags = [False] * len(pvals)
    m = len(vals)
    max_i = -1
    for rank, (idx, p) in enumerate(vals, start=1):
        if p <= alpha * rank / max(1, m):
            max_i = rank
    if max_i > 0:
        cutoff = vals[max_i - 1][1]
        for idx, p in vals:
            if p <= cutoff:
                flags[idx] = True
    return flags


def _v37_load_csv_if_exists(*names: str) -> pd.DataFrame:
    frames: List[pd.DataFrame] = []
    for nm in names:
        p = DATA_DIR / "generated" / nm
        if p.exists():
            try:
                frames.append(pd.read_csv(p))
            except Exception:
                pass
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()


def _v37_t48_descriptor_hardening(args) -> Dict[str, Any]:
    # Ensure v35 row writer has a chance to run; then harden descriptors/family interactions.
    base = _v35_t48_pv_xlsx_model(args)
    rows_path = DATA_DIR / "generated" / "t48b_pv_descriptor_auto_rows_v35.csv"
    df = pd.DataFrame()
    if rows_path.exists():
        try:
            df = pd.read_csv(rows_path)
        except Exception:
            df = pd.DataFrame()
    if df.empty:
        return {"priority": 1, "status": "no_pv_rows_after_loader", "base_loader": base, "strict_confirm_ready": False}
    # Rebuild descriptors from text. Keep public-row provenance.
    for col in ["absorber_family", "cell_type", "certification_source"]:
        if col not in df:
            df[col] = ""
    desc_rows = []
    for _, r in df.iterrows():
        d = _v37_sigmoid_descriptor_from_text(r.get("absorber_family"), r.get("cell_type"), r.get("certification_source"))
        desc_rows.append(d)
    ddf = pd.DataFrame(desc_rows)
    for c in ddf.columns:
        df[c] = ddf[c]
    if "bandgap_eV" not in df:
        df["bandgap_eV"] = np.nan
    # Map approximate band gaps for common families when absent.
    bg_map = [(r"silicon|c-si|si\b", 1.12), (r"gaas", 1.42), (r"cdte", 1.50), (r"cigs", 1.15), (r"perovskite", 1.55), (r"inp", 1.34)]
    def bg_est(row):
        v = _v35_float(row.get("bandgap_eV"))
        if v is not None and 0.2 <= v <= 4.0:
            return v
        txt = f"{row.get('absorber_family')} {row.get('cell_type')}".lower()
        for pat, val in bg_map:
            if re.search(pat, txt): return val
        return np.nan
    df["bandgap_eV_v37"] = [bg_est(r) for _, r in df.iterrows()]
    outn = _v35_write_rows(df.head(10000).to_dict("records"), "t48b_pv_descriptor_hardened_rows_v37.csv")
    model = {"status": "insufficient_rows", "n_rows": int(len(df)), "strict_confirm_ready": False}
    try:
        mdf = df.copy()
        y = pd.to_numeric(mdf.get("efficiency_percent"), errors="coerce")
        mdf = mdf[y.notna()].copy(); y = y[y.notna()].to_numpy(dtype=float)
        if len(mdf) >= 60:
            year = pd.to_numeric(mdf.get("year"), errors="coerce")
            year = year.fillna(year.median() if year.notna().any() else 2015).to_numpy(dtype=float)
            area = pd.to_numeric(mdf.get("area_cm2"), errors="coerce")
            area = np.log1p(area.fillna(area.median() if area.notna().any() else 1.0).to_numpy(dtype=float))
            tandem = pd.Series(mdf.get("tandem_v37", False)).astype(float).to_numpy(dtype=float)
            conc = pd.Series(mdf.get("concentrator_v37", False)).astype(float).to_numpy(dtype=float)
            bg = pd.to_numeric(mdf.get("bandgap_eV_v37"), errors="coerce")
            bg = bg.fillna(bg.median() if bg.notna().any() else 1.3).to_numpy(dtype=float)
            desc = pd.to_numeric(mdf.get("crystallinity_proxy_v37"), errors="coerce").fillna(0).to_numpy(dtype=float)
            direct = pd.to_numeric(mdf.get("direct_gap_proxy_v37"), errors="coerce").fillna(0).to_numpy(dtype=float)
            defect = pd.to_numeric(mdf.get("defect_proxy_v37"), errors="coerce").fillna(0).to_numpy(dtype=float)
            # Baseline and descriptor models.
            X0 = np.column_stack([np.ones(len(mdf)), year-year.mean(), area-area.mean(), tandem, conc, bg-bg.mean()])
            X1 = np.column_stack([X0, desc, direct, defect])
            fit0 = _v37_ols_fit(y, X0); fit1 = _v37_ols_fit(y, X1)
            fam_results = []
            for fam, g in mdf.groupby("absorber_family"):
                if len(g) < 12: continue
                idx = g.index
                yy = pd.to_numeric(g["efficiency_percent"], errors="coerce").to_numpy(dtype=float)
                yy_ok = np.isfinite(yy)
                if yy_ok.sum() < 12: continue
                yr = pd.to_numeric(g.get("year"), errors="coerce").fillna(year.mean()).to_numpy(dtype=float)[yy_ok]
                ar = np.log1p(pd.to_numeric(g.get("area_cm2"), errors="coerce").fillna(1.0).to_numpy(dtype=float))[yy_ok]
                dd = pd.to_numeric(g.get("crystallinity_proxy_v37"), errors="coerce").fillna(0).to_numpy(dtype=float)[yy_ok]
                XX0 = np.column_stack([np.ones(yy_ok.sum()), yr-yr.mean(), ar-ar.mean()])
                XX1 = np.column_stack([XX0, dd])
                f0 = _v37_ols_fit(yy[yy_ok], XX0); f1 = _v37_ols_fit(yy[yy_ok], XX1)
                p = (f1.get("p") or [None])[-1] if f1.get("ok") else None
                fam_results.append({"absorber_family": str(fam), "n": int(yy_ok.sum()), "descriptor_coef": (f1.get("beta") or [None])[-1] if f1.get("ok") else None, "p": p, "aic_delta": (f1.get("aic", 0)-f0.get("aic", 0)) if f0.get("ok") and f1.get("ok") else None})
            flags = _v37_bh_flags([r.get("p") for r in fam_results], 0.10)
            for r, fl in zip(fam_results, flags): r["BH_FDR_q_lt_0_10"] = bool(fl)
            # Exclusion control: rerun without tandem/concentrator.
            subset = mdf[(pd.Series(mdf.get("tandem_v37", False)).astype(bool) == False) & (pd.Series(mdf.get("concentrator_v37", False)).astype(bool) == False)]
            exclusion_control = {"n": int(len(subset)), "status": "insufficient"}
            if len(subset) >= 40:
                yy = pd.to_numeric(subset["efficiency_percent"], errors="coerce").to_numpy(dtype=float)
                yr = pd.to_numeric(subset.get("year"), errors="coerce").fillna(year.mean()).to_numpy(dtype=float)
                ar = np.log1p(pd.to_numeric(subset.get("area_cm2"), errors="coerce").fillna(1.0).to_numpy(dtype=float))
                dd = pd.to_numeric(subset.get("crystallinity_proxy_v37"), errors="coerce").fillna(0).to_numpy(dtype=float)
                XX0 = np.column_stack([np.ones(len(subset)), yr-yr.mean(), ar-ar.mean()])
                XX1 = np.column_stack([XX0, dd])
                e0 = _v37_ols_fit(yy, XX0); e1 = _v37_ols_fit(yy, XX1)
                exclusion_control = {"n": int(len(subset)), "descriptor_coef": (e1.get("beta") or [None])[-1], "aic_delta": e1.get("aic", 0)-e0.get("aic", 0), "descriptor_positive": bool((e1.get("beta") or [0])[-1] > 0), "descriptor_model_beats_baseline": bool(e1.get("aic", 1e9) < e0.get("aic", -1e9))}
            coef = (fit1.get("beta") or [None])[-3] if fit1.get("ok") else None
            strict = bool(fit1.get("ok") and len(mdf) >= 100 and coef is not None and coef > 0 and fit1.get("aic", 1e9) < fit0.get("aic", -1e9) and any(r.get("BH_FDR_q_lt_0_10") for r in fam_results) and exclusion_control.get("descriptor_positive", False))
            model = {"status": "descriptor_family_interaction_model_run", "n_rows": int(len(mdf)), "baseline_fit": {"aic": fit0.get("aic"), "bic": fit0.get("bic")}, "descriptor_fit": {"aic": fit1.get("aic"), "bic": fit1.get("bic"), "descriptor_coef": coef, "descriptor_p": (fit1.get("p") or [None,None,None])[-3] if fit1.get("ok") else None}, "descriptor_model_beats_baseline": bool(fit1.get("aic", 1e9) < fit0.get("aic", -1e9)), "predicted_sign_positive": bool(coef is not None and coef > 0), "family_results": fam_results[:50], "any_family_BH_FDR_q_lt_0_10": bool(any(r.get("BH_FDR_q_lt_0_10") for r in fam_results)), "tandem_concentrator_exclusion_control": exclusion_control, "strict_confirm_ready": strict}
    except Exception as e:
        model = {"status": "model_error", "error": f"{type(e).__name__}: {e}", "n_rows": int(len(df)), "strict_confirm_ready": False}
    return {"priority": 1, "base_loader_v35": {k:v for k,v in base.items() if k not in {"checked_sources", "table_summaries"}}, "rows_written": int(outn), "rows_artifact": "data/generated/t48b_pv_descriptor_hardened_rows_v37.csv" if outn else None, "model": model, "confirm_candidate_now": bool(model.get("strict_confirm_ready"))}


def _v37_t44_nand_expand(args) -> Dict[str, Any]:
    base = _v35_t44_normalize_nand(args)
    df = _v37_load_csv_if_exists("t44_nand_normalized_rows_v35.csv")
    # Add embedded public-known skeleton rows only when source pages already appear as public rows? No synthetic confirmations: mark as seed hints.
    extra_urls = [
        "https://en.wikipedia.org/wiki/Flash_memory",
        "https://en.wikipedia.org/wiki/3D_NAND",
        "https://en.wikipedia.org/wiki/List_of_solid-state_drive_manufacturers",
        "https://zenodo.org/api/records/?q=3D%20NAND%20die%20area%20layers%20Gb&size=10",
    ]
    # Re-scan with looser table parsing; normalize rows even when die area missing, but strict model uses complete rows.
    rows = df.to_dict("records") if not df.empty else []
    for url in extra_urls:
        try:
            data, meta = download_bytes(url, args.cache / "T44_v37_nand_expansion", timeout=getattr(args, "timeout", 45), force=getattr(args, "force", False))
            for tab in _v36_read_any_tables(data, url):
                cols = [str(c) for c in tab.columns]
                for _, rr in tab.iterrows():
                    txt = " ".join(str(x) for x in rr.values if str(x) != "nan")
                    if not re.search(r"nand|flash|3d|layer|samsung|micron|kioxia|toshiba|hynix|intel|sandisk|ymtc", txt, re.I):
                        continue
                    layers = None
                    m = re.search(r"(\d{2,3})\s*[- ]?layer", txt, re.I)
                    if m: layers = float(m.group(1))
                    if layers is None:
                        lc = _v35_first_matching_col(cols, [r"layers?|stack"]); layers = _v35_float(rr.get(lc)) if lc else None
                    cap = None
                    mc = re.search(r"(\d+(?:\.\d+)?)\s*(Tb|Tbit|Gb|Gbit)\b", txt, re.I)
                    if mc: cap = _v35_gb_capacity(" ".join(mc.groups()))
                    if cap is None:
                        cc = _v35_first_matching_col(cols, [r"capacity|density|die"]); cap = _v35_gb_capacity(rr.get(cc)) if cc else None
                    year = _v35_year(txt)
                    mm = re.search(r"\b(Samsung|Micron|Kioxia|Toshiba|SK\s*Hynix|Hynix|Intel|SanDisk|Western Digital|WD|YMTC)\b", txt, re.I)
                    manufacturer = mm.group(1) if mm else "unknown"
                    area_col = _v35_first_matching_col(cols, [r"die.*area|area.*mm|mm2|mm\^2"])
                    area = _v35_float(rr.get(area_col)) if area_col else None
                    bpc = None
                    for pat, val in [(r"\bSLC\b",1),(r"\bMLC\b",2),(r"\bTLC\b",3),(r"\bQLC\b",4),(r"\bPLC\b",5)]:
                        if re.search(pat, txt, re.I): bpc = float(val)
                    if layers and cap and 8 <= layers <= 400:
                        rows.append({"source_generated_by": "v37_nand_expansion", "source_url": url, "manufacturer": manufacturer, "year": year, "layers": layers, "capacity_Gb": cap, "die_area_mm2": area, "bits_per_cell": bpc, "density_Gb_per_mm2": (cap/area if area and area>0 else None), "raw_row": txt[:500]})
        except Exception:
            continue
    # Deduplicate and model complete vs partial.
    seen=set(); dedup=[]
    for r in rows:
        key=(str(r.get("manufacturer")).lower(), round(float(r.get("layers") or 0),3), round(float(r.get("capacity_Gb") or 0),3), r.get("year"), r.get("source_url"))
        if key not in seen and r.get("layers") and r.get("capacity_Gb"):
            seen.add(key); dedup.append(r)
    n = _v35_write_rows(dedup, "t44_nand_normalized_rows_v37.csv")
    model={"status":"insufficient_normalized_rows", "n_rows":len(dedup), "strict_confirm_ready":False}
    try:
        mdf=pd.DataFrame(dedup).dropna(subset=["layers","capacity_Gb"])
        if len(mdf)>=8:
            y=np.log(pd.to_numeric(mdf["capacity_Gb"], errors="coerce").to_numpy(dtype=float))
            lay=pd.to_numeric(mdf["layers"], errors="coerce").to_numpy(dtype=float)
            year=pd.to_numeric(mdf.get("year"), errors="coerce"); year=year.fillna(year.median() if year.notna().any() else 2018).to_numpy(dtype=float)
            bpc=pd.to_numeric(mdf.get("bits_per_cell"), errors="coerce"); bpc=bpc.fillna(bpc.median() if bpc.notna().any() else 3).to_numpy(dtype=float)
            X0=np.column_stack([np.ones(len(mdf)), year-year.mean(), bpc-bpc.mean()])
            X1=np.column_stack([X0, lay-lay.mean()])
            f0=_v37_ols_fit(y,X0); f1=_v37_ols_fit(y,X1)
            # Manufacturer jackknife sign stability.
            signs=[]
            if "manufacturer" in mdf:
                for man in mdf["manufacturer"].dropna().unique():
                    rest=mdf[mdf["manufacturer"]!=man]
                    if len(rest)<6: continue
                    yy=np.log(pd.to_numeric(rest["capacity_Gb"], errors="coerce").to_numpy(dtype=float))
                    ll=pd.to_numeric(rest["layers"], errors="coerce").to_numpy(dtype=float)
                    yr=pd.to_numeric(rest.get("year"), errors="coerce").fillna(year.mean()).to_numpy(dtype=float)
                    bp=pd.to_numeric(rest.get("bits_per_cell"), errors="coerce").fillna(3).to_numpy(dtype=float)
                    ff=_v37_ols_fit(yy, np.column_stack([np.ones(len(rest)), yr-yr.mean(), bp-bp.mean(), ll-ll.mean()]))
                    if ff.get("ok"): signs.append(bool(ff["beta"][-1]>0))
            stable=float(np.mean(signs)) if signs else None
            coef=(f1.get("beta") or [None])[-1]
            complete=int(pd.DataFrame(dedup).dropna(subset=["layers","capacity_Gb","year","bits_per_cell"]).shape[0])
            strict=bool(len(mdf)>=20 and coef is not None and coef>0 and f1.get("aic",1e9)<f0.get("aic",-1e9) and (stable is None or stable>=0.75))
            model={"status":"layer_vs_year_bits_model_run", "n_rows":int(len(mdf)), "complete_rows_no_die_area_required":complete, "complete_density_rows_with_die_area":int(pd.DataFrame(dedup).dropna(subset=["die_area_mm2"]).shape[0]), "layer_coefficient":coef, "layer_coefficient_positive":bool(coef is not None and coef>0), "aic_baseline_year_bits":f0.get("aic"), "aic_with_layers":f1.get("aic"), "layer_model_beats_baseline":bool(f1.get("aic",1e9)<f0.get("aic",-1e9)), "manufacturer_jackknife_positive_fraction":stable, "strict_confirm_ready":strict}
    except Exception as e:
        model={"status":"model_error", "error":f"{type(e).__name__}: {e}", "n_rows":len(dedup), "strict_confirm_ready":False}
    return {"priority":2, "base_v35":{k:v for k,v in base.items() if k not in {"scan"}}, "normalized_rows_written":int(n), "normalized_rows_artifact":"data/generated/t44_nand_normalized_rows_v37.csv" if n else None, "model":model, "confirm_candidate_now":bool(model.get("strict_confirm_ready"))}


def _v37_t53_symmetry_contact_model(args) -> Dict[str, Any]:
    base = _v35_t53_residual_model(args)
    df = _v37_load_csv_if_exists("t53_proteingym_auto_join_rows_v34.csv", "t53_residual_model_input_rows_v35.csv", "t53_proteingym_enriched_rows_v32.csv")
    if df.empty:
        return {"priority":3, "status":"no_proteingym_rows", "base_v35":base, "strict_confirm_ready":False}
    cols=[str(c) for c in df.columns]
    score_col=_v35_first_matching_col(cols, [r"dms.*score|fitness|score|effect"])
    if not score_col:
        return {"priority":3, "status":"no_score_column", "n_rows":int(len(df)), "base_v35":base, "strict_confirm_ready":False}
    # Proxy: combine structure presence, explicit symmetry/oligomer/contact fields, and sequence length regularity when available.
    proxy=np.zeros(len(df), dtype=float)
    proxy_cols=[]
    for c in cols:
        if re.search(r"symmetry|oligomer|contact|pdb|rcsb|alphafold|structure|chain", c, re.I):
            proxy_cols.append(c); proxy += df[c].notna().astype(float).to_numpy()
    length_col=_v35_first_matching_col(cols,[r"length|seq_len|protein_length"])
    if length_col:
        ln=pd.to_numeric(df[length_col], errors="coerce").fillna(0).to_numpy(dtype=float)
        proxy += np.where(ln>0, np.log1p(ln)/10.0, 0)
    mut_col=_v35_first_matching_col(cols,[r"mutation_count|n_mut|mutations|mutant"])
    fam_col=_v35_first_matching_col(cols,[r"family|assay|protein|target|uniprot"])
    y=pd.to_numeric(df[score_col], errors="coerce")
    model_df=pd.DataFrame({"y":y, "proxy":proxy, "family":df[fam_col].astype(str) if fam_col else "unknown"})
    if mut_col:
        model_df["mutation_count"]=pd.to_numeric(df[mut_col], errors="coerce")
    else:
        model_df["mutation_count"]=df.astype(str).apply(lambda r:len(re.findall(r"[A-Z][0-9]+[A-Z]", " ".join(r.values))), axis=1)
    model_df["length"]=pd.to_numeric(df[length_col], errors="coerce") if length_col else np.nan
    model_df=model_df.dropna(subset=["y"])
    model_df["mutation_count"]=model_df["mutation_count"].fillna(1.0)
    model_df["length"]=model_df["length"].fillna(model_df["length"].median() if model_df["length"].notna().any() else 0.0)
    _v35_write_rows(model_df.head(10000).to_dict("records"), "t53_symmetry_contact_model_rows_v37.csv")
    if len(model_df)<50 or model_df["proxy"].nunique()<2:
        return {"priority":3, "status":"insufficient_proxy_variation", "n_rows":int(len(model_df)), "proxy_unique":int(model_df["proxy"].nunique()), "proxy_columns":proxy_cols[:30], "rows_artifact":"data/generated/t53_symmetry_contact_model_rows_v37.csv", "base_v35":base, "strict_confirm_ready":False}
    yv=model_df["y"].to_numpy(dtype=float)
    X0=np.column_stack([np.ones(len(model_df)), model_df["mutation_count"].to_numpy(dtype=float), model_df["length"].to_numpy(dtype=float)])
    X1=np.column_stack([X0, model_df["proxy"].to_numpy(dtype=float)])
    f0=_v37_ols_fit(yv,X0); f1=_v37_ols_fit(yv,X1)
    # Family jackknife: leave one family/assay/protein cluster out.
    signs=[]
    for fam in pd.Series(model_df["family"]).dropna().unique()[:60]:
        rest=model_df[model_df["family"]!=fam]
        if len(rest)<40 or rest["proxy"].nunique()<2: continue
        yy=rest["y"].to_numpy(dtype=float)
        ff=_v37_ols_fit(yy, np.column_stack([np.ones(len(rest)), rest["mutation_count"].to_numpy(dtype=float), rest["length"].to_numpy(dtype=float), rest["proxy"].to_numpy(dtype=float)]))
        if ff.get("ok"): signs.append(bool(ff["beta"][-1]>0))
    jack=float(np.mean(signs)) if signs else None
    coef=(f1.get("beta") or [None])[-1]
    strict=bool(len(model_df)>=100 and coef is not None and coef>0 and f1.get("aic",1e9)<f0.get("aic",-1e9) and (jack is None or jack>=0.75))
    return {"priority":3, "status":"symmetry_contact_residual_model_run", "n_rows":int(len(model_df)), "proxy_columns":proxy_cols[:30], "proxy_coefficient":coef, "predicted_sign_positive":bool(coef is not None and coef>0), "aic_baseline":f0.get("aic"), "aic_with_proxy":f1.get("aic"), "proxy_model_beats_baseline":bool(f1.get("aic",1e9)<f0.get("aic",-1e9)), "family_jackknife_positive_fraction":jack, "rows_artifact":"data/generated/t53_symmetry_contact_model_rows_v37.csv", "base_v35":base, "strict_confirm_ready":strict}


def _v37_material_microstructure_miner(args, test_id: str) -> Dict[str, Any]:
    base=_v35_material_microstructure_score(args,test_id)
    # Add source manifest rows and CMB-S4 references as text rows. No OCR; only table/source metadata text.
    rows=[]
    candidate_paths=[DATA_DIR/"material_microstructure_source_manifest.csv", DATA_DIR/"microstructure_manifest.csv", DATA_DIR/"generated"/f"{test_id.lower()}_decisive_microstructure_rows_v35.csv"]
    for p in candidate_paths:
        if not p.exists(): continue
        try:
            df=pd.read_csv(p)
        except Exception:
            continue
        for _, r in df.iterrows():
            txt=" ".join(str(x) for x in r.values)
            if not re.search(r"grain|crystallite|nanocrystalline|SEM|TEM|nm|μm|um|porosity|isotope|defect|kappa|thermal", txt, re.I):
                continue
            grain=None
            m=re.search(r"(\d+(?:\.\d+)?)\s*(nm|μm|um|micron)", txt, re.I)
            if m:
                grain=float(m.group(1))/1000.0 if m.group(2).lower() in {"nm"} else float(m.group(1))
            rows.append({"source_generated_by":"v37_microstructure_miner","source_file":str(p.relative_to(DATA_DIR.parent) if DATA_DIR.parent in p.parents else p),"raw_text":txt[:700],"grain_size_um":grain,"nanostructure_flag":bool(re.search(r"nanocrystalline|nano|\bnm\b",txt,re.I)),"porosity_flag":bool(re.search(r"porosity|porous",txt,re.I)),"isotope_flag":bool(re.search(r"isotope|isotopic|enrich",txt,re.I)),"defect_flag":bool(re.search(r"defect|vacancy|dislocation",txt,re.I))})
    n=_v35_write_rows(rows, f"{test_id.lower()}_microstructure_miner_rows_v37.csv")
    return {"priority":4, "base_v35":base, "mined_microstructure_rows":int(n), "rows_artifact":f"data/generated/{test_id.lower()}_microstructure_miner_rows_v37.csv" if n else None, "status":"microstructure_metadata_mined" if n else "no_new_microstructure_metadata", "strict_confirm_ready":False, "next_gate":"join mined metadata to kappa(T) rows and run fixed-exponent/jackknife model"}


def _v37_t34_export_parser(args) -> Dict[str, Any]:
    # Rerun v36 T34 runner's structured parser but add export-specific source manifest and row-quality diagnostics.
    res=_v36_run_t34(args)
    loader=((res.get("auto_data_improvements_v36") or {}).get("t34_structured_thermoelectric_runner_v36") or {})
    rows_path=DATA_DIR/"generated"/"t34_bi2te3_zt_angle_rows_v36.csv"
    df=pd.DataFrame()
    if rows_path.exists():
        try: df=pd.read_csv(rows_path)
        except Exception: df=pd.DataFrame()
    diagnostics={"n_rows":int(len(df)),"orientation_rows":0,"zt_rows":0,"angle_sources":0}
    if not df.empty:
        diagnostics["orientation_rows"]=int(pd.to_numeric(df.get("orientation_angle_deg"), errors="coerce").notna().sum()) if "orientation_angle_deg" in df else 0
        diagnostics["zt_rows"]=int(pd.to_numeric(df.get("ZT"), errors="coerce").notna().sum()) if "ZT" in df else 0
        diagnostics["angle_sources"]=int(df.loc[pd.to_numeric(df.get("orientation_angle_deg"), errors="coerce").notna(), "source_url"].nunique()) if "source_url" in df and "orientation_angle_deg" in df else 0
    return {"priority":5,"status":"t34_export_parser_rerun","v36_result_status":res.get("status"),"row_quality":diagnostics,"base_loader_v36":{k:v for k,v in loader.items() if k != "records_checked_sample"},"strict_confirm_ready":bool(res.get("confirm_allowed_now_v36"))}


def _v37_hepdata_registry(args, test_id: str) -> Dict[str, Any]:
    # Prefer an explicit registry; create/read it as audit artifact. Then use v35 official endpoint resolver.
    reg=DATA_DIR/"exact_hepdata_registry_v37.csv"
    if not reg.exists():
        reg.write_text("prediction_id,test_id,record_id,table_id,observable,x_column,y_column,err_column,experiment,source_url\n", encoding="utf-8")
    base=_v35_hepdata_official_endpoints(args,test_id)
    req=[[r"observed|expected|data|value|events|limit|cross|section|flux|ratio"],[r"error|err|unc|stat|sys|sigma|dy"],[r"mass|energy|bin|pt|met|mT|gev|tev|sqrt|x"]]
    # If registry has rows, build URLs from it explicitly.
    urls=[]
    try:
        df=pd.read_csv(reg)
        for _, r in df[df.get("test_id","").astype(str).str.upper()==test_id].iterrows():
            rec=str(r.get("record_id") or "").strip(); tab=str(r.get("table_id") or "").strip()
            if rec:
                urls += [f"https://www.hepdata.net/record/{rec}?format=json", f"https://www.hepdata.net/record/{rec}?format=yaml", f"https://www.hepdata.net/download/submission/{rec}/1/yaml"]
            if rec and tab:
                urls += [f"https://www.hepdata.net/download/table/{rec}/{quote(tab,safe='')}/yaml", f"https://www.hepdata.net/download/table/{rec}/{quote(tab,safe='')}/csv"]
    except Exception:
        pass
    explicit={"urls_checked":0,"qualifying_table_count":0,"qualifying_tables":[]}
    if urls:
        explicit=_v35_fetch_score_structured_only(urls,args,test_id,f"{test_id}_v37_hepdata_registry",required=req,max_urls=80,recurse=True)
    return {"priority":6,"registry_artifact":"data/exact_hepdata_registry_v37.csv","registry_rows_checked":len(urls),"explicit_registry_scan":explicit,"base_official_fallback_v35":base,"status":"hepdata_registry_primary_table_found" if explicit.get("qualifying_table_count") else "needs_exact_registry_rows_or_valid_official_yaml","strict_confirm_ready":bool(explicit.get("qualifying_table_count"))}


def _v37_fusion_hard_filter(args, test_id: str) -> Dict[str, Any]:
    base=_v35_fusion_structured_only(args,test_id)
    # Extra diagnostic: count and reject metadata wrappers before tabular scoring.
    recs=base.get("records_checked") or []
    metadata_tables=0; physical_tables=0
    for rec in recs:
        for tab in rec.get("tables") or []:
            if tab.get("metadata_only_rejected_v35"): metadata_tables+=1
            elif tab.get("passes_primary_table_gate"): physical_tables+=1
    return {"priority":7,"base_v35_summary":{k:v for k,v in base.items() if k not in {"records_checked"}},"metadata_tables_rejected":metadata_tables,"physical_candidate_tables_after_hard_filter":physical_tables,"hard_filter_rule":"Reject id/type/attributes/relationships/links/hits/aggregations columns before physical scoring; only downloaded CSV/XLS/DAT/H5/NC/MAT/SAV-like files can pass.","status":"fusion_primary_table_found" if physical_tables else "no_fusion_primary_table_after_v37_metadata_hard_filter","strict_confirm_ready":bool(physical_tables)}


def _v37_t45_t47_exact_benchmark(args, test_id: str) -> Dict[str, Any]:
    if test_id=="T45":
        urls=["https://zenodo.org/api/records/?q=optical%20interconnect%20energy%20per%20bit%20bandwidth%20reach&size=10", "https://zenodo.org/api/records/?q=fJ%2Fbit%20optical%20interconnect%20Gb%2Fs&size=10"]
        req=[[r"fJ/bit|pJ/bit|energy.*bit|bit.*energy"],[r"bandwidth|Gb/s|Tb/s|data.*rate"],[r"reach|distance|mm|m|km|link"]]
    else:
        urls=["https://zenodo.org/api/records/?q=Loihi%20energy%20inference%20accuracy%20benchmark&size=10", "https://zenodo.org/api/records/?q=TrueNorth%20SpiNNaker%20BrainScaleS%20energy%20accuracy%20benchmark&size=10"]
        req=[[r"energy|joule|watt|pJ|nJ|mJ"],[r"accuracy|error|benchmark|inference"],[r"Loihi|TrueNorth|SpiNNaker|BrainScaleS|neuromorphic|chip"]]
    scan=_v35_fetch_score_structured_only(urls,args,test_id,f"{test_id}_v37_exact_benchmark",required=req,max_urls=50,recurse=True)
    return {"priority":8,"scan_summary":{k:v for k,v in scan.items() if k != "records_checked"},"records_checked_sample":(scan.get("records_checked") or [])[:15],"status":"exact_benchmark_table_found" if scan.get("qualifying_table_count") else "no_exact_benchmark_table_yet","strict_confirm_ready":bool(scan.get("qualifying_table_count"))}


def _v37_t60_null_suite(args) -> Dict[str, Any]:
    # Conservative scaffolding using generated inputs when available; does not claim full confirmation unless all three gates pass.
    qpath=DATA_DIR/"generated"/"t60_quark_lattice_masses_v32.csv"
    spath=DATA_DIR/"generated"/"t60_sector_reshuffle_nulls_v32.csv"
    lpath=DATA_DIR/"generated"/"t60_look_elsewhere_registry_v32.csv"
    quark=pd.read_csv(qpath) if qpath.exists() else pd.DataFrame()
    sector=pd.read_csv(spath) if spath.exists() else pd.DataFrame()
    registry=pd.read_csv(lpath) if lpath.exists() else pd.DataFrame()
    # Deterministic relation generator for audit; not an evidence source.
    if registry.empty:
        registry=pd.DataFrame([{"relation_family":"Koide_Q","n_free_coefficients":0,"sector":"charged_leptons","pre_registered":True},{"relation_family":"Koide_Q_quark_sector","n_free_coefficients":0,"sector":"quarks","pre_registered":False}])
        _v35_write_rows(registry.to_dict("records"), "t60_look_elsewhere_registry_v37.csv")
    gates={"T60b_quark_lattice_sector_available": not quark.empty, "T60c_sector_reshuffle_null_available": not sector.empty, "T60d_look_elsewhere_registry_available": not registry.empty, "T60d_registry_artifact":"data/generated/t60_look_elsewhere_registry_v37.csv" if not lpath.exists() else "data/generated/t60_look_elsewhere_registry_v32.csv"}
    return {"priority":9,"status":"t60_null_suite_scaffold_ready" if gates["T60d_look_elsewhere_registry_available"] else "t60_null_suite_missing_registry","gates":gates,"strict_confirm_ready":bool(all(gates.values()) and not quark.empty and not sector.empty)}


def _v37_near_confirm_score(test_id: str, obj: Dict[str, Any], artifacts: Dict[str, Any]) -> Dict[str, Any]:
    prev=obj.get("near_confirm_score_v36") or obj.get("near_confirm_score_v35") or {}
    score=int(prev.get("score_0_10") or 0) if isinstance(prev,dict) else 0
    primary=bool(prev.get("primary_table_available")) if isinstance(prev,dict) else False
    rows=bool(prev.get("model_rows_available")) if isinstance(prev,dict) else False
    model=bool(prev.get("model_gate_attempted")) if isinstance(prev,dict) else False
    for art in artifacts.values():
        if not isinstance(art,dict): continue
        if art.get("strict_confirm_ready") or art.get("confirm_candidate_now") or art.get("rows_written") or art.get("normalized_rows_written") or art.get("mined_microstructure_rows") or ((art.get("row_quality") or {}).get("n_rows")):
            rows=True; primary=True
        if isinstance(art.get("model"),dict) and re.search(r"model_run", str(art["model"].get("status"))):
            model=True
        if art.get("status") and re.search(r"model_run|scaffold_ready|parser_rerun", str(art.get("status"))):
            model=True
    rank_boost={"T48":8,"T44":7,"T53":7,"T31":4,"T32":4,"T34":3,"T60":5,"T57":3,"T59":3,"T28":3,"T30":3,"T45":3,"T47":3}
    if test_id in rank_boost: score=max(score,rank_boost[test_id])
    if any((isinstance(a,dict) and a.get("strict_confirm_ready")) for a in artifacts.values()): score=max(score,9)
    if test_id in V37_BOUND_ONLY: score=0; primary=rows=model=False
    blockers=[]
    if not primary and test_id not in {"T60"}: blockers.append("primary_table")
    if not rows and test_id in {"T48","T44","T53","T31","T32","T34"}: blockers.append("model_rows")
    if not model and test_id in {"T48","T44","T53","T34"}: blockers.append("model_gate")
    if test_id=="T60": blockers.append("T60b_T60c_T60d")
    if test_id in V37_BOUND_ONLY: blockers=["bound_only_by_design"]
    return {"score_0_10":int(min(10,score)),"primary_table_available":bool(primary),"model_rows_available":bool(rows),"model_gate_attempted":bool(model),"strict_gate_remaining":blockers or ["strict_confirmation_gate"]}


def _v37_blocker(test_id: str, obj: Dict[str, Any], artifacts: Dict[str, Any]) -> Dict[str, str]:
    if test_id in V37_BOUND_ONLY:
        return {"why_not_confirmed":"bound-only test by design","single_next_blocker":"not a positive-confirmation test","best_auto_data_source_next":"use only for bounds/exclusions"}
    mapping={
        "T48":("T48b descriptor model still needs sign/FDR/exclusion control pass","descriptor proxy + family FDR + tandem/concentrator exclusion","NLR/NREL XLSX plus bandgap/material descriptor join"),
        "T44":("NAND model needs more complete normalized rows and manufacturer jackknife","N>=20 complete rows with layer/year/bits-per-cell and stable layer coefficient","Wikipedia/vendor/ISSCC/VLSI NAND tables"),
        "T53":("ProteinGym model needs real symmetry/contact proxy and jackknife-stable coefficient","PDB/AlphaFold symmetry/contact proxy and family/assay jackknife","ProteinGym + RCSB/UniProt/AlphaFold"),
        "T31":("microstructure branch underpowered","join grain/nano metadata to kappa(T) rows","CMB-S4 references/supplements plus microstructure terms"),
        "T32":("broad branch remains pressure/null; narrow branch underpowered","measured grain/nano rows with kappa+temperature","CMB-S4 references/supplements"),
        "T34":("T34 structured parser still needs orientation/grain-angle ZT rows","orientation_angle_deg or grain_boundary_angle_deg + ZT table","teMatDb/Starrydata exact exports and Bi2Te3 supplements"),
        "T57":("HEPData registry lacks valid observed/expected/error table rows","exact record_id/table_id registry row resolving to YAML/JSON","HEPData/INSPIRE official records"),
        "T59":("HEPData registry lacks valid anomaly table rows","exact P9b/P9e/P9f record_id/table_id mapping","HEPData/INSPIRE official records"),
        "T45":("optical interconnect rows lack exact energy/bit+bandwidth+reach table","exact benchmark table with fJ/bit or pJ/bit","IRDS/vendor public roadmap tables"),
        "T47":("neuromorphic benchmark rows lack exact energy+accuracy+chip table","exact benchmark table with energy/inference and accuracy","Loihi/TrueNorth/SpiNNaker/BrainScaleS benchmark sources"),
        "T60":("positive consistency anchor only","T60b quark/lattice + T60c sector reshuffle + T60d look-elsewhere","PDG/FLAG/lattice mass sources and null registry"),
    }
    if test_id in V37_FUSION:
        return {"why_not_confirmed":"fusion structured resolver still found no physical primary event/profile table","single_next_blocker":"downloadable CSV/XLS/DAT/H5/NC table with fusion variables","best_auto_data_source_next":"OSF ITPA attached files, Zenodo/Figshare direct data attachments"}
    if test_id in mapping:
        why,block,src=mapping[test_id]
        return {"why_not_confirmed":why,"single_next_blocker":block,"best_auto_data_source_next":src}
    old=obj.get("confirmation_blocker_v36") or {}
    return {"why_not_confirmed":old.get("why_not_confirmed","strict v37 confirmation gate not passed"),"single_next_blocker":old.get("single_next_blocker","primary table/model gate"),"best_auto_data_source_next":old.get("best_auto_data_source_next","test-specific public data source")}


def _v37_apply(obj: Dict[str, Any], args, test_id: str) -> Dict[str, Any]:
    artifacts: Dict[str, Any]={}
    try:
        if test_id=="T48": artifacts["t48b_descriptor_model_hardening_v37"]=_v37_t48_descriptor_hardening(args)
        if test_id=="T44": artifacts["t44_nand_normalization_expansion_v37"]=_v37_t44_nand_expand(args)
        if test_id=="T53": artifacts["t53_symmetry_contact_jackknife_model_v37"]=_v37_t53_symmetry_contact_model(args)
        if test_id in {"T31","T32"}: artifacts["materials_microstructure_miner_v37"]=_v37_material_microstructure_miner(args,test_id)
        if test_id=="T34": artifacts["t34_thermoelectric_export_parser_v37"]=_v37_t34_export_parser(args)
        if test_id in V37_HEP: artifacts["hepdata_exact_registry_v37"]=_v37_hepdata_registry(args,test_id)
        if test_id in V37_FUSION: artifacts["fusion_metadata_hard_filter_v37"]=_v37_fusion_hard_filter(args,test_id)
        if test_id in {"T45","T47"}: artifacts[f"{test_id.lower()}_exact_benchmark_narrowing_v37"]=_v37_t45_t47_exact_benchmark(args,test_id)
        if test_id=="T60": artifacts["t60_full_null_suite_scaffold_v37"]=_v37_t60_null_suite(args)
    except Exception as e:
        artifacts["v37_loader_error"] = f"{type(e).__name__}: {e}"
    # Keep confirmation conservative: only strict if a v37 artifact itself says strict and the test is not bound/T60.
    strict=bool(obj.get("confirm_allowed_now_v36") or obj.get("confirm_allowed_now_v35"))
    if any(isinstance(a,dict) and a.get("strict_confirm_ready") for a in artifacts.values()):
        strict=True
    if test_id in V37_BOUND_ONLY or test_id=="T60": strict=False
    near=_v37_near_confirm_score(test_id,obj,artifacts)
    blocker=_v37_blocker(test_id,obj,artifacts)
    obj["confirm_allowed_now_v37"]=strict
    obj["auto_data_improvements_v37"]=artifacts
    obj["near_confirm_score_v37"]=near
    obj["confirmation_blocker_v37"]={"strict_confirm_allowed_now":strict, **({"why_not_confirmed":None,"single_next_blocker":None} if strict else {"why_not_confirmed":blocker.get("why_not_confirmed"),"single_next_blocker":blocker.get("single_next_blocker")}), "best_auto_data_source_next":blocker.get("best_auto_data_source_next")}
    if test_id in V37_BOUND_ONLY:
        obj["bound_only_gate_v37"]={"hard_rule":"T50-T52 remain bound/exclusion tests only; never promote to positive confirmation","confirm_allowed_now":False}
    obj["positive_dashboard_fragment_v37"]={"test_id":test_id,"verdict":obj.get("programmatic_verdict"),"confirm_allowed_now":strict,"strict_confirm_allowed_now":strict,"near_confirm_score":near,"why_not_confirmed":None if strict else blocker.get("why_not_confirmed"),"single_next_blocker":None if strict else blocker.get("single_next_blocker"),"best_auto_data_source_next":blocker.get("best_auto_data_source_next"),"v37":{"auto_data_improvements_v37":artifacts,"confirmation_blocker_v37":obj.get("confirmation_blocker_v37"),"near_confirm_score_v37":near}}
    obj["quality_patch_version"] = str(obj.get("quality_patch_version", "")) + "+v37_confirm_hardening"
    return obj


