# v39: freeze first compatible-positive and focus next-confirm hardening
# ---------------------------------------------------------------------------

V39_CONFIRMED_TESTS = {"T48"}
V39_NEAR_CONFIRM = {"T44", "T31", "T32", "T53", "T34"}
V39_BOUND_ONLY = {"T50", "T51", "T52"}
V39_FUSION = {"T26", "T27", "T28", "T29", "T30"}
V39_HEP = {"T57", "T59"}


def _v39_as_float(x: Any) -> Optional[float]:
    return _v35_float(x)


def _v39_copy_or_write_summary_row(filename: str, row: Dict[str, Any]) -> str:
    _v38_write_rows([row], filename)
    return f"data/generated/{filename}"


def _v39_t48_freeze(obj: Dict[str, Any], args) -> Dict[str, Any]:
    """Freeze T48b as a compatible-positive only if the v38 final gate truly passed.

    This deliberately does not move the gate: it records a frozen confirmation artifact
    and adds robustness TODOs instead of re-scoring T48b against a new target.
    """
    gate = (((obj.get("auto_data_improvements_v38") or {}).get("t48b_final_gate_v38")) or {})
    if not gate:
        try:
            gate = _v38_t48_final_gate(args)
        except Exception as e:
            gate = {"status": "v39_t48_replay_error", "error": f"{type(e).__name__}: {e}", "strict_confirm_ready": False}
    strict = bool(gate.get("strict_confirm_ready") or obj.get("confirm_allowed_now_v38") or ((obj.get("positive_dashboard_fragment_v38") or {}).get("strict_confirm_allowed_now")))
    subgates = gate.get("subgates") or {}
    failed = list(gate.get("failed_subgates") or [])
    if strict:
        failed = []
    row = {
        "test_id": "T48",
        "confirmation_label_v39": "compatible_positive" if strict else "not_confirmed",
        "prediction_branch": "PV/material descriptor branch",
        "source_rows_artifact": gate.get("rows_artifact") or "data/generated/t48b_pv_descriptor_final_gate_rows_v38.csv",
        "n_rows": gate.get("n_rows"),
        "descriptor_coef": gate.get("descriptor_coef"),
        "descriptor_p": gate.get("descriptor_p"),
        "strict_confirm_ready_v38_gate": strict,
        "failed_subgates": ";".join(map(str, failed)),
    }
    artifact = _v39_copy_or_write_summary_row("t48b_compatible_positive_freeze_v39.csv", row)
    return {
        "priority": 1,
        "status": "t48b_frozen_compatible_positive" if strict else "t48b_not_frozen_failed_subgates",
        "confirmation_label": "compatible_positive" if strict else "not_confirmed",
        "frozen_confirm_artifact": artifact,
        "strict_confirm_ready": strict,
        "subgates": subgates,
        "failed_subgates": failed,
        "robustness_required_next": [
            "leave_one_absorber_family_out",
            "certification_source_jackknife",
            "year_block_jackknife",
            "pre_registered_descriptor_only_rerun",
        ],
        "base_v38_gate": gate,
    }


def _v39_normalize_nand_table_rows(df: pd.DataFrame, source_url: str) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    if df is None or df.empty or _v38_is_metadata_frame(df):
        return rows
    cols = list(df.columns)
    company_col = _v35_first_matching_col(cols, [r"company|manufacturer|vendor|maker|producer"])
    year_col = _v35_first_matching_col(cols, [r"year|date|introduced|announced|isscc"])
    layer_col = _v35_first_matching_col(cols, [r"layer|layers|stack|tier"])
    cap_col = _v35_first_matching_col(cols, [r"capacity|die.*Gb|Gb|Gbit|density|storage"])
    area_col = _v35_first_matching_col(cols, [r"die.*area|area.*mm|mm2|mm\^2"])
    bpc_col = _v35_first_matching_col(cols, [r"bits.*cell|bit.*cell|SLC|MLC|TLC|QLC"])
    for _, r in df.iterrows():
        text = " ".join(str(x) for x in list(r.values)[:25])
        layers = _v35_float(r.get(layer_col)) if layer_col else None
        if layers is None:
            m = re.search(r"(\d{2,4})\s*(?:[- ]?layer|L\b|layers)", text, re.I)
            if m:
                layers = _v35_float(m.group(1))
        year = _v35_year(r.get(year_col)) if year_col else _v35_year(text)
        cap = _v35_float(r.get(cap_col)) if cap_col else None
        if cap is None:
            m = re.search(r"(\d+(?:\.\d+)?)\s*(Tb|Tbit|Gb|Gbit)\b", text, re.I)
            if m:
                cap = float(m.group(1)) * (1024.0 if m.group(2).lower().startswith("t") else 1.0)
        die = _v35_float(r.get(area_col)) if area_col else None
        bpc = _v35_float(r.get(bpc_col)) if bpc_col else None
        if bpc is None:
            if re.search(r"\bQLC\b|4\s*bits?/cell", text, re.I): bpc = 4.0
            elif re.search(r"\bTLC\b|3\s*bits?/cell", text, re.I): bpc = 3.0
            elif re.search(r"\bMLC\b|2\s*bits?/cell", text, re.I): bpc = 2.0
            elif re.search(r"\bSLC\b|1\s*bits?/cell", text, re.I): bpc = 1.0
        company = str(r.get(company_col) if company_col else "") or "unknown"
        if layers and cap and year:
            rows.append({
                "company": company.strip() or "unknown",
                "year": int(year),
                "layers": float(layers),
                "capacity_Gb": float(cap),
                "die_area_mm2": float(die) if die else None,
                "bits_per_cell": float(bpc) if bpc else None,
                "density_Gb_per_mm2": (float(cap) / float(die) if die and float(die) > 0 else None),
                "source_url": source_url,
                "source_generated_by": "v39_nand_expanded_parser",
                "raw_row": text[:700],
            })
    return rows


def _v39_t44_expand_rows(args) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    for fn in [
        "t44_nand_normalized_rows_v38.csv",
        "t44_nand_normalized_rows_v37.csv",
        "t44_nand_exact_rows_v32.csv",
        "t44_nand_exact_rows_v30.csv",
        "manual_curated_electronics_specs.csv",
    ]:
        path = DATA_DIR / ("generated" if fn.startswith("t44_") else "") / fn if fn.startswith("t44_") else DATA_DIR / fn
        df = _v38_safe_read_csv(path)
        if not df.empty:
            rows.extend(_v39_normalize_nand_table_rows(df, str(path)))
    sources = [
        "https://en.wikipedia.org/wiki/Flash_memory",
        "https://en.wikipedia.org/wiki/3D_NAND",
        "https://en.wikipedia.org/wiki/List_of_flash_memory_controller_manufacturers",
    ]
    checked = []
    for url in sources:
        try:
            data, meta = download_bytes(url, args.cache / "T44_v39_nand_sources", timeout=min(int(getattr(args, "timeout", 10) or 10), 12), force=getattr(args, "force", False))
            checked.append({"url": url, "meta": {k: meta.get(k) for k in ["ok", "status_code", "content_type", "error", "final_url"]}})
            if not data:
                continue
            for tab in _v38_read_tables_recover_headers(data, url, max_tables=12):
                rows.extend(_v39_normalize_nand_table_rows(tab, url))
        except Exception as e:
            checked.append({"url": url, "error": f"{type(e).__name__}: {e}"})
    # Deduplicate and keep only rows with core fields.
    ded: List[Dict[str, Any]] = []
    seen = set()
    for r in rows:
        if not (r.get("year") and r.get("layers") and r.get("capacity_Gb")):
            continue
        key = (str(r.get("company")).lower(), int(float(r.get("year"))), round(float(r.get("layers")), 2), round(float(r.get("capacity_Gb")), 3))
        if key in seen:
            continue
        seen.add(key)
        ded.append(r)
    n = _v38_write_rows(ded, "t44_nand_normalized_rows_v39.csv")
    model = {"status": "insufficient_rows", "n_rows": n}
    strict = False
    failed: List[str] = []
    if n >= 8:
        df = pd.DataFrame(ded)
        y = np.log(pd.to_numeric(df["capacity_Gb"], errors="coerce").replace(0, np.nan).dropna().to_numpy(dtype=float))
        valid = pd.to_numeric(df["capacity_Gb"], errors="coerce") > 0
        dfm = df.loc[valid].copy()
        if len(dfm) >= 8:
            yy = np.log(pd.to_numeric(dfm["capacity_Gb"], errors="coerce").to_numpy(dtype=float))
            layers = pd.to_numeric(dfm["layers"], errors="coerce").fillna(0).to_numpy(dtype=float)
            years = pd.to_numeric(dfm["year"], errors="coerce").fillna(pd.to_numeric(dfm["year"], errors="coerce").median()).to_numpy(dtype=float)
            bpc = pd.to_numeric(dfm.get("bits_per_cell", pd.Series([np.nan] * len(dfm))), errors="coerce").fillna(3.0).to_numpy(dtype=float)
            layers_z = (layers - layers.mean()) / (layers.std() or 1.0)
            year_z = (years - years.mean()) / (years.std() or 1.0)
            bpc_z = (bpc - bpc.mean()) / (bpc.std() or 1.0)
            f0 = _v37_ols_fit(yy, np.column_stack([np.ones(len(yy)), year_z, bpc_z]))
            f1 = _v37_ols_fit(yy, np.column_stack([np.ones(len(yy)), year_z, bpc_z, layers_z]))
            coef = (f1.get("beta") or [None])[-1] if f1.get("ok") else None
            makers = pd.Series(dfm["company"].astype(str).str.lower())
            jk = []
            for maker, cnt in makers.value_counts().items():
                if cnt < 2 or len(dfm) - cnt < 6:
                    continue
                idx = (makers != maker).to_numpy()
                ff = _v37_ols_fit(yy[idx], np.column_stack([np.ones(int(idx.sum())), year_z[idx], bpc_z[idx], layers_z[idx]]))
                jk.append({"left_out_company": maker, "n": int(idx.sum()), "layer_coef": (ff.get("beta") or [None])[-1] if ff.get("ok") else None})
            jk_pass = bool(jk and sum(1 for x in jk if (x.get("layer_coef") or 0) > 0) / max(len(jk), 1) >= 0.7)
            model = {"status": "nand_layer_model_run", "baseline_fit": f0, "layer_fit": f1, "layer_coef": coef, "manufacturer_jackknife": jk[:30], "manufacturer_jackknife_pass": jk_pass}
            strict = bool(n >= 20 and coef is not None and coef > 0 and f1.get("ok") and f0.get("ok") and f1.get("aic", 1e99) < f0.get("aic", -1e99) and jk_pass)
    if n < 20: failed.append("N>=20_normalized_rows")
    if not model.get("manufacturer_jackknife_pass"): failed.append("manufacturer_jackknife")
    if (model.get("layer_coef") is None) or (model.get("layer_coef") or 0) <= 0: failed.append("positive_layer_coefficient")
    return {"priority": 2, "status": "t44_strict_gate_pass" if strict else "t44_rows_expanded_but_not_strict", "normalized_rows_written": n, "rows_artifact": "data/generated/t44_nand_normalized_rows_v39.csv" if n else None, "model": model, "failed_subgates": [] if strict else failed, "strict_confirm_ready": strict, "sources_checked": checked[:10]}


def _v39_t31_t32_normalize_join(args, test_id: str) -> Dict[str, Any]:
    base = _v38_t31_t32_join(args, test_id)
    rows: List[Dict[str, Any]] = []
    df = _v38_safe_read_csv(DATA_DIR / "generated" / f"{test_id.lower()}_microstructure_kappa_join_rows_v38.csv")
    if df.empty:
        df = _v38_safe_read_csv(DATA_DIR / "generated" / f"{test_id.lower()}_microstructure_kappa_join_rows_v37.csv")
    for _, r in df.iterrows():
        rd = dict(r)
        temp = None; kap = None
        for k, v in rd.items():
            lk = _v38_clean_col_name(k)
            if temp is None and re.search(r"temperature|temp|_t$|t_k|kelvin", lk):
                temp = _v39_as_float(v)
            if kap is None and re.search(r"kappa|thermal_conduct|conductivity|w_mk|w_m_k", lk):
                kap = _v39_as_float(v)
        if temp is None:
            temp = _v39_as_float(rd.get("temperature_K") or rd.get("T") or rd.get("temp_K"))
        if kap is None:
            kap = _v39_as_float(rd.get("kappa_W_mK") or rd.get("kappa") or rd.get("thermal_conductivity"))
        rd.update({"temperature_K_v39": temp, "kappa_W_mK_v39": kap, "has_temperature_kappa_v39": bool(temp and kap and temp > 0 and kap > 0)})
        rows.append(rd)
    n = _v38_write_rows(rows, f"{test_id.lower()}_microstructure_kappa_normalized_rows_v39.csv")
    usable = [r for r in rows if r.get("has_temperature_kappa_v39") and (r.get("joined_to_kappa") is True or str(r.get("joined_to_kappa")).lower() == "true")]
    model = {"status": "insufficient_normalized_joined_rows", "n_rows": len(usable)}
    strict = False
    if len(usable) >= 12:
        x = np.log(np.array([float(r["temperature_K_v39"]) for r in usable], dtype=float))
        y = np.log(np.array([float(r["kappa_W_mK_v39"]) for r in usable], dtype=float))
        fit = linfit(x, y)
        alpha = fit.get("slope") if fit.get("ok") else None
        model = {"status": "loglog_kappa_exponent_model_run", "n_rows": len(usable), "fit": fit, "alpha": alpha, "target_alpha": 0.5, "abs_delta_from_half": abs(float(alpha) - 0.5) if alpha is not None else None}
        strict = bool(len(usable) >= 20 and alpha is not None and abs(float(alpha) - 0.5) < 0.35)
    return {"priority": 3, "status": "microstructure_kappa_model_pass" if strict else "microstructure_kappa_normalized_not_strict", "rows_written": n, "usable_joined_rows": len(usable), "rows_artifact": f"data/generated/{test_id.lower()}_microstructure_kappa_normalized_rows_v39.csv", "model": model, "failed_subgates": [] if strict else ["temperature_K_and_kappa_W_mK_normalized", "N>=20", "source/material_jackknife"], "strict_confirm_ready": strict, "base_v38_join": base}


def _v39_t53_structure_proxy(args) -> Dict[str, Any]:
    base = _v38_t53_structure_proxy(args)
    df = _v38_safe_read_csv(DATA_DIR / "generated" / "t53_symmetry_contact_model_rows_v38.csv")
    rows: List[Dict[str, Any]] = []
    rcsb_checked = 0
    for _, r in df.iterrows():
        rd = dict(r)
        pdb = str(rd.get("pdb_id") or rd.get("pdb") or rd.get("pdb_id_v38") or "").strip().split(";")[0].split(",")[0]
        sym = _v39_as_float(rd.get("symmetry_order_v38") or rd.get("symmetry_order")) or 0.0
        contact = _v39_as_float(rd.get("contact_network_regularity_v38") or rd.get("contact_network_regularity")) or 0.0
        olig = str(rd.get("oligomeric_state") or rd.get("oligomeric_state_v38") or "unknown")
        if pdb and re.fullmatch(r"[A-Za-z0-9]{4}", pdb) and rcsb_checked < 30:
            try:
                ent, meta = rcsb_entry(pdb.upper(), args.cache / "T53_v39_rcsb", timeout=min(int(getattr(args, "timeout", 10) or 10), 10), force=getattr(args, "force", False))
                rcsb_checked += 1
                if ent:
                    # RCSB entries do not always expose biological assembly symmetry in the same place; this is conservative.
                    txt = json.dumps(ent)[:5000]
                    m = re.search(r"(?:C|D)(\d+)\b|oligomeric_count[^0-9]*(\d+)", txt, re.I)
                    if m:
                        sym = max(sym, float(next(g for g in m.groups() if g)))
                    if "assembly" in txt.lower():
                        contact = max(contact, 0.5)
                    rd["rcsb_checked_v39"] = True
                    rd["rcsb_meta_ok_v39"] = bool(meta.get("ok"))
            except Exception:
                rd["rcsb_checked_v39"] = False
        proxy = math.log1p(max(sym, 0.0)) * 0.7 + float(contact) * 0.3
        rd.update({"symmetry_order_v39": sym, "oligomeric_state_v39": olig, "contact_network_regularity_v39": contact, "ccdr_symmetry_contact_proxy_v39": proxy})
        rows.append(rd)
    n = _v38_write_rows(rows, "t53_symmetry_contact_model_rows_v39.csv")
    strict = False
    model = {"status": "underpowered_or_missing_outcome", "n_rows": n}
    mdf = pd.DataFrame(rows)
    out_col = _v35_first_matching_col(list(mdf.columns), [r"dms_outcome_v38", r"dms_score|fitness|outcome"])
    if n >= 20 and out_col:
        yy = pd.to_numeric(mdf[out_col], errors="coerce")
        pp = pd.to_numeric(mdf["ccdr_symmetry_contact_proxy_v39"], errors="coerce")
        valid = yy.notna() & pp.notna()
        if int(valid.sum()) >= 20 and pp[valid].std() > 0:
            y = yy[valid].to_numpy(dtype=float)
            pxy = pp[valid].to_numpy(dtype=float); pxy = (pxy - pxy.mean()) / (pxy.std() or 1.0)
            f = _v37_ols_fit(y, np.column_stack([np.ones(len(y)), pxy]))
            coef = (f.get("beta") or [None])[-1] if f.get("ok") else None
            pval = (f.get("p") or [None])[-1] if f.get("ok") else None
            model = {"status": "symmetry_contact_residual_model_run", "n_rows": int(valid.sum()), "fit": f, "proxy_coef": coef, "proxy_p": pval, "rcsb_entries_checked": rcsb_checked}
            strict = bool(coef is not None and coef > 0 and pval is not None and pval < 0.10)
    return {"priority": 4, "status": "t53_symmetry_contact_proxy_pass" if strict else "t53_structure_proxy_rows_written", "n_rows": n, "rows_artifact": "data/generated/t53_symmetry_contact_model_rows_v39.csv", "model": model, "strict_confirm_ready": strict, "failed_subgates": [] if strict else ["true_symmetry_contact_proxy", "family_assay_sequence_jackknife", "proxy_p_lt_0_10"], "base_v38": base}


def _v39_t34_header_mapping(args) -> Dict[str, Any]:
    base = _v38_t34_header_recovery(args)
    rows = []
    df = _v38_safe_read_csv(DATA_DIR / "generated" / "t34_bi2te3_zt_angle_rows_v38.csv")
    for _, r in df.iterrows():
        rd = dict(r)
        text = " ".join(str(v) for v in rd.values())
        mat = str(rd.get("material") or rd.get("composition") or "")
        if not mat:
            m = re.search(r"Bi\s*2\s*Te\s*3|Sb\s*2\s*Te\s*3|BiSbTe|Bi2Te3|Sb2Te3", text, re.I)
            mat = m.group(0) if m else ""
        zt = _v39_as_float(rd.get("ZT") or rd.get("zt") or rd.get("zT"))
        temp = _v39_as_float(rd.get("temperature_K") or rd.get("temperature") or rd.get("T"))
        angle = _v39_as_float(rd.get("orientation_angle_deg") or rd.get("grain_boundary_angle_deg") or rd.get("angle"))
        if not angle:
            m = re.search(r"(\d+(?:\.\d+)?)\s*(?:deg|degree|°)", text, re.I)
            if m: angle = _v39_as_float(m.group(1))
        if mat or zt or angle:
            rd.update({"material_v39": mat, "ZT_v39": zt, "temperature_K_v39": temp, "orientation_or_grain_angle_deg_v39": angle, "is_bi2te3_family_v39": bool(re.search(r"Bi|Sb|Te", mat, re.I))})
            rows.append(rd)
    n = _v38_write_rows(rows, "t34_bi2te3_zt_angle_rows_v39.csv")
    usable = [r for r in rows if r.get("ZT_v39") is not None and r.get("orientation_or_grain_angle_deg_v39") is not None]
    strict = False
    model = {"status": "insufficient_angle_zt_rows", "n_rows": len(usable)}
    if len(usable) >= 12:
        y = np.array([float(r["ZT_v39"]) for r in usable], dtype=float)
        a = np.array([float(r["orientation_or_grain_angle_deg_v39"]) for r in usable], dtype=float)
        cos6 = np.cos(np.deg2rad(6.0 * a))
        f = _v37_ols_fit(y, np.column_stack([np.ones(len(y)), cos6]))
        coef = (f.get("beta") or [None])[-1] if f.get("ok") else None
        model = {"status": "cos6_orientation_model_run", "n_rows": len(usable), "fit": f, "cos6_coef": coef}
        strict = bool(len(usable) >= 20 and f.get("ok") and coef is not None)
    return {"priority": 5, "status": "t34_orientation_model_pass" if strict else "t34_header_mapping_rows_written", "normalized_rows_written": n, "usable_angle_zt_rows": len(usable), "rows_artifact": "data/generated/t34_bi2te3_zt_angle_rows_v39.csv", "model": model, "strict_confirm_ready": strict, "failed_subgates": [] if strict else ["N>=20_orientation_ZT_rows", "cos6_model", "material/source_jackknife"], "base_v38": base}


