def _v39_near_score(test_id: str, strict: bool, obj: Dict[str, Any], arts: Dict[str, Any]) -> Dict[str, Any]:
    prev = obj.get("near_confirm_score_v38") or obj.get("near_confirm_score_v37") or {}
    score = int(prev.get("score_0_10") or 0) if isinstance(prev, dict) else 0
    remaining = [] if strict else list((prev or {}).get("strict_gate_remaining") or ["strict_confirmation_gate"])
    if test_id == "T48" and strict:
        score = 10; remaining = []
    elif test_id == "T44":
        score = max(score, 8 if ((arts.get("t44_nand_expansion_v39") or {}).get("normalized_rows_written") or 0) >= 12 else 7)
    elif test_id in {"T31", "T32"}:
        score = max(score, 5 if ((arts.get("microstructure_kappa_normalization_v39") or {}).get("usable_joined_rows") or 0) else 4)
    elif test_id == "T53":
        score = max(score, 7 if ((arts.get("t53_real_structure_proxy_v39") or {}).get("n_rows") or 0) >= 20 else 6)
    elif test_id == "T34":
        score = max(score, 4 if ((arts.get("t34_header_mapping_v39") or {}).get("normalized_rows_written") or 0) else 2)
    elif test_id == "T60":
        score = max(score, 5)
    return {"score_0_10": int(min(10, score)), "primary_table_available": bool(strict or (prev or {}).get("primary_table_available") or score >= 7), "model_rows_available": bool(strict or (prev or {}).get("model_rows_available") or score >= 6), "model_gate_attempted": bool(strict or (prev or {}).get("model_gate_attempted") or score >= 7), "strict_gate_remaining": remaining}


def _v39_blocker(test_id: str, strict: bool) -> Dict[str, Any]:
    if strict:
        return {"why_not_confirmed": None, "single_next_blocker": None, "best_auto_data_source_next": None}
    mapping = {
        "T44": ("NAND model still lacks strict row-count/manufacturer jackknife gate", "expand to >=20 normalized rows and manufacturer jackknife", "Wikipedia/vendor/ISSCC/VLSI NAND public tables"),
        "T31": ("microstructure rows are not fully normalized to kappa(T)", "temperature_K/kappa_W_mK normalization + source/material jackknife", "CMB-S4 thermal rows + source-paper microstructure metadata"),
        "T32": ("narrow grain/nano branch lacks normalized kappa(T) model", "temperature_K/kappa_W_mK normalization + exponent model", "CMB-S4 thermal rows + microstructure miner"),
        "T53": ("ProteinGym route needs real structural proxy and jackknife stability", "PDB/AlphaFold symmetry/contact proxy + assay/family/sequence jackknife", "ProteinGym + UniProt/PDB/RCSB/AlphaFold"),
        "T34": ("thermoelectric orientation/ZT rows are still insufficient", "recover headers and map >=20 Bi2Te3/Sb2Te3 orientation/grain-angle rows", "teMatDb/Starrydata exact exports"),
        "T57": ("HEPData exact registry is still not filled with observed/expected/error columns", "exact record/table/column registry", "HEPData official YAML/JSON submission"),
        "T59": ("HEPData anomaly ledger registry is still not exact", "exact record/table/column registry", "HEPData/INSPIRE mapping"),
        "T60": ("T60a is anchor-only; full null suite is not passed", "T60b/T60c/T60d", "PDG/FLAG + pre-registered relation registry"),
    }
    if test_id in V39_BOUND_ONLY:
        return {"why_not_confirmed": "bound-only test by design", "single_next_blocker": "not confirmable as positive support", "best_auto_data_source_next": "use only as bound/exclusion"}
    if test_id in V39_FUSION:
        return {"why_not_confirmed": "fusion remains lower priority until exact public measurement files are found", "single_next_blocker": "downloadable machine-readable measurement table", "best_auto_data_source_next": "ITPA DB measurement file or DIII-D/JET/AUG supplements"}
    if test_id in {"T45", "T47"}:
        return {"why_not_confirmed": "exact benchmark table not yet found", "single_next_blocker": "public benchmark rows with exact units", "best_auto_data_source_next": "IRDS/vendor optical or neuromorphic benchmark supplements"}
    if test_id in mapping:
        why, block, src = mapping[test_id]
        return {"why_not_confirmed": why, "single_next_blocker": block, "best_auto_data_source_next": src}
    return {"why_not_confirmed": "strict v39 gate not passed", "single_next_blocker": "primary/model/jackknife gate", "best_auto_data_source_next": "test-specific public structured source"}


def _v39_apply(obj: Dict[str, Any], args, test_id: str) -> Dict[str, Any]:
    arts: Dict[str, Any] = {}
    try:
        if test_id == "T48": arts["t48b_frozen_compatible_positive_v39"] = _v39_t48_freeze(obj, args)
        if test_id == "T44": arts["t44_nand_expansion_v39"] = _v39_t44_expand_rows(args)
        if test_id in {"T31", "T32"}: arts["microstructure_kappa_normalization_v39"] = _v39_t31_t32_normalize_join(args, test_id)
        if test_id == "T53": arts["t53_real_structure_proxy_v39"] = _v39_t53_structure_proxy(args)
        if test_id == "T34": arts["t34_header_mapping_v39"] = _v39_t34_header_mapping(args)
        if test_id in V39_HEP: arts["hepdata_exact_registry_v39"] = _v39_hepdata_registry(args, test_id)
        if test_id in V39_FUSION: arts["fusion_lower_priority_resolver_v39"] = _v39_fusion_lower_priority(args, test_id)
        if test_id in {"T45", "T47"}: arts[f"{test_id.lower()}_exact_parser_v39"] = _v39_t45_t47_parser(args, test_id)
        if test_id == "T60": arts["t60_full_null_suite_v39"] = _v39_t60_null_suite(args)
    except Exception as e:
        arts["v39_loader_error"] = f"{type(e).__name__}: {e}"
    strict = bool(obj.get("confirm_allowed_now_v38"))
    if test_id == "T48":
        strict = bool((arts.get("t48b_frozen_compatible_positive_v39") or {}).get("strict_confirm_ready"))
    if any(isinstance(a, dict) and a.get("strict_confirm_ready") for a in arts.values()):
        strict = True
    if test_id in V39_BOUND_ONLY or test_id == "T60":
        strict = False
    label = "compatible_positive" if strict and test_id == "T48" else ("strict_confirmed" if strict else ("positive_anchor_only" if test_id == "T60" else "not_confirmed"))
    near = _v39_near_score(test_id, strict, obj, arts)
    blocker = _v39_blocker(test_id, strict)
    obj["confirm_allowed_now_v39"] = strict
    obj["confirmation_label_v39"] = label
    obj["auto_data_improvements_v39"] = arts
    obj["near_confirm_score_v39"] = near
    obj["confirmation_blocker_v39"] = {"strict_confirm_allowed_now": strict, **blocker}
    if test_id in V39_BOUND_ONLY:
        obj["bound_only_gate_v39"] = {"hard_rule": "T50-T52 remain bound/exclusion tests only; never promote to positive confirmation", "confirm_allowed_now": False}
    obj["positive_dashboard_fragment_v39"] = {
        "test_id": test_id,
        "verdict": obj.get("programmatic_verdict"),
        "confirmation_label": label,
        "confirm_allowed_now": strict,
        "strict_confirm_allowed_now": strict,
        "near_confirm_score": near,
        "why_not_confirmed": blocker.get("why_not_confirmed"),
        "single_next_blocker": blocker.get("single_next_blocker"),
        "best_auto_data_source_next": blocker.get("best_auto_data_source_next"),
        "v39": {"auto_data_improvements_v39": arts, "confirmation_blocker_v39": obj["confirmation_blocker_v39"], "near_confirm_score_v39": near},
    }
    obj["quality_patch_version"] = str(obj.get("quality_patch_version", "")) + "+v39_confirm_freeze_and_next_targets"
    return obj


