# v39.1: override T34 with a direct no-broad-download runner. The older v38 T34
# header recovery can touch remote thermoelectric exports and may be slow on some
# networks; this runner only consumes already generated/cache artifacts and emits
# a real data-limited JSON if no rows are present.
def _v39_run_t34_fast(args) -> Dict[str, Any]:
    result = common_header("T34")
    rows: List[Dict[str, Any]] = []
    for fn in ["t34_bi2te3_zt_angle_rows_v38.csv", "t34_bi2te3_zt_angle_rows_v37.csv", "t34_bi2te3_zt_angle_rows_v36.csv"]:
        df = _v38_safe_read_csv(DATA_DIR / "generated" / fn)
        if df.empty:
            continue
        for _, r in df.iterrows():
            rd = dict(r)
            text = " ".join(str(v) for v in rd.values())
            mat = str(rd.get("material") or rd.get("material_v39") or rd.get("composition") or "")
            if not mat:
                m = re.search(r"Bi\s*2\s*Te\s*3|Sb\s*2\s*Te\s*3|BiSbTe|Bi2Te3|Sb2Te3", text, re.I)
                mat = m.group(0) if m else ""
            zt = _v39_as_float(rd.get("ZT_v39") or rd.get("ZT") or rd.get("zt") or rd.get("zT"))
            temp = _v39_as_float(rd.get("temperature_K_v39") or rd.get("temperature_K") or rd.get("temperature") or rd.get("T"))
            angle = _v39_as_float(rd.get("orientation_or_grain_angle_deg_v39") or rd.get("orientation_angle_deg") or rd.get("grain_boundary_angle_deg") or rd.get("angle"))
            if mat or zt or angle:
                rd.update({"material_v39": mat, "ZT_v39": zt, "temperature_K_v39": temp, "orientation_or_grain_angle_deg_v39": angle, "is_bi2te3_family_v39": bool(re.search(r"Bi|Sb|Te", mat, re.I))})
                rows.append(rd)
    n = _v38_write_rows(rows, "t34_bi2te3_zt_angle_rows_v39.csv")
    usable = [r for r in rows if r.get("ZT_v39") is not None and r.get("orientation_or_grain_angle_deg_v39") is not None]
    model = {"status": "insufficient_angle_zt_rows", "n_rows": len(usable)}
    strict = False
    if len(usable) >= 12:
        y = np.array([float(r["ZT_v39"]) for r in usable], dtype=float)
        a = np.array([float(r["orientation_or_grain_angle_deg_v39"]) for r in usable], dtype=float)
        cos6 = np.cos(np.deg2rad(6.0 * a))
        fit = _v37_ols_fit(y, np.column_stack([np.ones(len(y)), cos6]))
        model = {"status": "cos6_orientation_model_run", "n_rows": len(usable), "fit": fit, "cos6_coef": (fit.get("beta") or [None])[-1] if fit.get("ok") else None}
        strict = bool(len(usable) >= 20 and fit.get("ok"))
    loader = {"priority": 5, "status": "t34_v39_fast_rows_mapped" if n else "t34_v39_no_cached_orientation_rows", "normalized_rows_written": n, "usable_angle_zt_rows": len(usable), "rows_artifact": "data/generated/t34_bi2te3_zt_angle_rows_v39.csv", "model": model, "strict_confirm_ready": strict, "failed_subgates": [] if strict else ["N>=20_orientation_ZT_rows", "cos6_model", "material/source_jackknife"], "download_policy": "no broad download in direct T34 fast path"}
    near = {"score_0_10": int(4 if n else 2), "primary_table_available": bool(n), "model_rows_available": bool(n), "model_gate_attempted": model.get("status") == "cos6_orientation_model_run", "strict_gate_remaining": [] if strict else loader["failed_subgates"]}
    result.update({
        "schema": "ccdr-tierb-result-v39-t34-fast-header-mapping",
        "status": "ok_t34_v39_fast_header_mapping" if n else "data_limited_no_cached_t34_orientation_rows",
        "programmatic_verdict": "data_limited_positive_path_ready",
        "analysis_note": "v39 direct T34 path: timeout-safe header/row mapping from generated thermoelectric artifacts; no broad crawling.",
        "auto_data_improvements_v39": {"t34_header_mapping_v39": loader},
        "confirm_allowed_now_v39": strict,
        "confirmation_label_v39": "strict_confirmed" if strict else "not_confirmed",
        "near_confirm_score_v39": near,
        "confirmation_blocker_v39": {"strict_confirm_allowed_now": strict, "why_not_confirmed": None if strict else "thermoelectric orientation/ZT rows are still insufficient", "single_next_blocker": None if strict else "recover headers and map >=20 Bi2Te3/Sb2Te3 orientation/grain-angle rows", "best_auto_data_source_next": "teMatDb/Starrydata exact exports"},
        "positive_dashboard_fragment_v39": {"test_id": "T34", "verdict": "data_limited_positive_path_ready", "confirmation_label": "strict_confirmed" if strict else "not_confirmed", "confirm_allowed_now": strict, "strict_confirm_allowed_now": strict, "near_confirm_score": near, "why_not_confirmed": None if strict else "thermoelectric orientation/ZT rows are still insufficient", "single_next_blocker": None if strict else "recover headers and map >=20 Bi2Te3/Sb2Te3 orientation/grain-angle rows", "best_auto_data_source_next": "teMatDb/Starrydata exact exports", "v39": {"auto_data_improvements_v39": {"t34_header_mapping_v39": loader}, "near_confirm_score_v39": near}},
        "quality_patch_version": "v39_fast_t34_header_mapping",
    })
    return result

SPECIAL_RUNNERS["T34"] = _v39_run_t34_fast

