def _v40_norm_float(x: Any) -> Optional[float]:
    if x is None:
        return None
    if isinstance(x, (int, float)) and math.isfinite(float(x)):
        return float(x)
    s = str(x).strip().replace(',', '')
    if not s or s.lower() in {'nan', 'none', 'null'}:
        return None
    m = re.search(r'[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?', s)
    if not m:
        return None
    try:
        return float(m.group(0))
    except Exception:
        return None


def _v40_read_any_csv(names: Sequence[str]) -> pd.DataFrame:
    frames: List[pd.DataFrame] = []
    for fn in names:
        p = DATA_DIR / 'generated' / fn
        df = _v38_safe_read_csv(p)
        if not df.empty:
            df['__source_artifact'] = str(p)
            frames.append(df)
    if not frames:
        return pd.DataFrame()
    try:
        return pd.concat(frames, ignore_index=True, sort=False)
    except Exception:
        return frames[0]


def _v40_text_of_row(rd: Dict[str, Any]) -> str:
    return ' '.join(str(v) for v in rd.values() if v is not None)


def _v40_t48_robustness(obj: Dict[str, Any], args) -> Dict[str, Any]:
    """Keep T48b frozen; only add robustness bookkeeping and artifacts."""
    strict_prev = bool(obj.get('confirm_allowed_now_v39') or obj.get('confirm_allowed_now_v38'))
    rows = []
    for fn in [
        't48b_compatible_positive_freeze_v39.csv',
        't48b_pv_descriptor_final_gate_rows_v38.csv',
        't48b_pv_descriptor_hardened_rows_v37.csv',
        't48b_pv_descriptor_auto_rows_v35.csv',
        't48b_pv_descriptor_rows_v29.csv',
    ]:
        df = _v38_safe_read_csv(DATA_DIR / 'generated' / fn)
        if df.empty:
            continue
        for _, r in df.head(2000).iterrows():
            rd = dict(r)
            rows.append(rd)
    if rows:
        _v38_write_rows(rows[:2000], 't48b_robustness_audit_rows_v40.csv')
    family_col = None
    if rows:
        keys = set().union(*(r.keys() for r in rows[:50]))
        for pat in ['absorber', 'family', 'material_class', 'Eff. Chart Material Class']:
            hit = [k for k in keys if pat.lower() in str(k).lower()]
            if hit:
                family_col = hit[0]
                break
    families = sorted({str(r.get(family_col)) for r in rows if family_col and str(r.get(family_col, '')).strip()})[:50]
    status = 't48b_frozen_compatible_positive_robustness_pending' if strict_prev else 't48b_not_frozen_gate_missing'
    return {
        'priority': 1,
        'status': status,
        'strict_confirm_ready': strict_prev,
        'confirmation_label': 'compatible_positive' if strict_prev else 'not_confirmed',
        'frozen_confirm_artifact': 'data/generated/t48b_compatible_positive_freeze_v39.csv',
        'robustness_artifact': 'data/generated/t48b_robustness_audit_rows_v40.csv' if rows else None,
        'robustness_next_checks': ['leave_one_absorber_family_out', 'certification_source_jackknife', 'year_block_jackknife', 'descriptor_only_rerun'],
        'n_audit_rows_seen': len(rows),
        'families_seen_sample': families,
    }


def _v40_t44_tier_filter(args) -> Dict[str, Any]:
    df = _v40_read_any_csv(['t44_nand_normalized_rows_v39.csv', 't44_nand_normalized_rows_v38.csv', 't44_nand_normalized_rows_v37.csv', 't44_nand_exact_rows_v32.csv', 't44_nand_exact_rows_v30.csv'])
    rows: List[Dict[str, Any]] = []
    for _, r in df.iterrows():
        rd = dict(r)
        text = _v40_text_of_row(rd)
        company = str(rd.get('company') or rd.get('manufacturer') or rd.get('maker') or rd.get('vendor') or '')
        year = _v40_norm_float(rd.get('year'))
        layers = _v40_norm_float(rd.get('layers') or rd.get('layer_count'))
        capacity = _v40_norm_float(rd.get('capacity_Gb') or rd.get('die_capacity_Gb') or rd.get('capacity_gb') or rd.get('capacity'))
        die_area = _v40_norm_float(rd.get('die_area_mm2') or rd.get('area_mm2') or rd.get('die_area'))
        bpc = _v40_norm_float(rd.get('bits_per_cell') or rd.get('bpc'))
        # Regex fallbacks from text.
        if layers is None:
            m = re.search(r'(\d{2,3})\s*[- ]?(?:layer|L)\b', text, re.I)
            if m: layers = float(m.group(1))
        if year is None:
            m = re.search(r'\b(20\d{2}|19\d{2})\b', text)
            if m: year = float(m.group(1))
        if bpc is None:
            if re.search(r'\bTLC\b|3\s*bits?\s*/?cell', text, re.I): bpc = 3.0
            elif re.search(r'\bQLC\b|4\s*bits?\s*/?cell', text, re.I): bpc = 4.0
            elif re.search(r'\bMLC\b|2\s*bits?\s*/?cell', text, re.I): bpc = 2.0
            elif re.search(r'\bSLC\b|1\s*bits?\s*/?cell', text, re.I): bpc = 1.0
        if capacity is None:
            m = re.search(r'(\d+(?:\.\d+)?)\s*(Tb|Tbit|Gb|Gbit)\b', text, re.I)
            if m:
                capacity = float(m.group(1)) * (1000.0 if m.group(2).lower().startswith('t') else 1.0)
        density = _v40_norm_float(rd.get('density_Gb_per_mm2') or rd.get('density'))
        if density is None and capacity and die_area and die_area > 0:
            density = capacity / die_area
        tier = 'C'
        if company and year and layers and capacity and die_area and bpc:
            tier = 'A'
        elif company and year and layers and (capacity or density) and bpc:
            tier = 'B'
        rd.update({
            'company_v40': company,
            'year_v40': year,
            'layers_v40': layers,
            'capacity_Gb_v40': capacity,
            'die_area_mm2_v40': die_area,
            'bits_per_cell_v40': bpc,
            'density_Gb_per_mm2_v40': density,
            'nand_row_quality_tier_v40': tier,
            'confirm_eligible_v40': tier in {'A', 'B'},
        })
        rows.append(rd)
    _v38_write_rows(rows, 't44_nand_audited_tier_rows_v40.csv')
    eligible = [r for r in rows if r.get('confirm_eligible_v40') and r.get('layers_v40') and (r.get('density_Gb_per_mm2_v40') or r.get('capacity_Gb_v40'))]
    model: Dict[str, Any] = {'status': 'insufficient_tier_a_b_rows', 'n_rows': len(eligible)}
    strict = False
    if len(eligible) >= 12:
        yvals = np.array([float(r.get('density_Gb_per_mm2_v40') or r.get('capacity_Gb_v40')) for r in eligible], dtype=float)
        x1 = np.array([float(r.get('layers_v40')) for r in eligible], dtype=float)
        year = np.array([float(r.get('year_v40') or np.nan) for r in eligible], dtype=float)
        bpc = np.array([float(r.get('bits_per_cell_v40') or 0.0) for r in eligible], dtype=float)
        good = np.isfinite(yvals) & np.isfinite(x1) & np.isfinite(year)
        if int(good.sum()) >= 8:
            y = np.log(np.maximum(yvals[good], 1e-9))
            X = np.column_stack([np.ones(int(good.sum())), np.log(np.maximum(x1[good], 1e-9)), year[good] - np.nanmin(year[good]), bpc[good]])
            fit = _v37_ols_fit(y, X)
            coef = (fit.get('beta') or [None, None])[1] if fit.get('ok') else None
            companies = {str(r.get('company_v40')) for r in eligible if r.get('company_v40')}
            model = {'status': 'tier_a_b_layer_model_run', 'n_rows': int(good.sum()), 'fit': fit, 'layer_coef': coef, 'n_companies': len(companies)}
            strict = bool(int(good.sum()) >= 20 and coef is not None and coef > 0 and len(companies) >= 3)
    tier_counts = {t: sum(1 for r in rows if r.get('nand_row_quality_tier_v40') == t) for t in ['A','B','C']}
    failed = [] if strict else ['N>=20_tier_A_B_rows', 'positive_layer_coefficient', 'manufacturer_jackknife']
    return {'priority': 2, 'status': 't44_tier_filtered_strict_pass' if strict else 't44_tier_filtered_not_strict', 'rows_artifact': 'data/generated/t44_nand_audited_tier_rows_v40.csv', 'tier_counts': tier_counts, 'eligible_rows': len(eligible), 'model': model, 'failed_subgates': failed, 'strict_confirm_ready': strict}


def _v40_extract_temp_kappa(rd: Dict[str, Any]) -> Tuple[Optional[float], Optional[float], Optional[float]]:
    text = _v40_text_of_row(rd)
    temp = _v40_norm_float(rd.get('temperature_K_v39') or rd.get('temperature_K') or rd.get('T_K') or rd.get('T') or rd.get('temp_K'))
    kap = _v40_norm_float(rd.get('kappa_W_mK_v39') or rd.get('kappa_W_mK') or rd.get('thermal_conductivity') or rd.get('kappa') or rd.get('K'))
    grain = _v40_norm_float(rd.get('grain_size_nm') or rd.get('grain_size_um') or rd.get('grain_size') or rd.get('crystallite_size'))
    if temp is None:
        m = re.search(r'(\d+(?:\.\d+)?)\s*K\b', text, re.I)
        if m: temp = float(m.group(1))
    if kap is None:
        m = re.search(r'(?:kappa|κ|thermal conductivity)[^\d]{0,20}(\d+(?:\.\d+)?)', text, re.I)
        if m: kap = float(m.group(1))
    if grain is None:
        m = re.search(r'(\d+(?:\.\d+)?)\s*(nm|µm|um|micron)', text, re.I)
        if m:
            val = float(m.group(1)); unit = m.group(2).lower()
            grain = val if unit == 'nm' else val * 1000.0
    return temp, kap, grain


def _v40_t31_t32_normalization(args, test_id: str) -> Dict[str, Any]:
    files = [f'{test_id.lower()}_microstructure_kappa_normalized_rows_v39.csv', f'{test_id.lower()}_microstructure_kappa_join_rows_v38.csv', f'{test_id.lower()}_microstructure_miner_rows_v37.csv', 'grain_size_known_manifest_v32.csv', 'grain_size_known_manifest_v30.csv']
    df = _v40_read_any_csv(files)
    rows: List[Dict[str, Any]] = []
    for _, r in df.iterrows():
        rd = dict(r)
        temp, kap, grain = _v40_extract_temp_kappa(rd)
        text = _v40_text_of_row(rd).lower()
        micro = 'nanocrystalline' if 'nanocrystal' in text or (grain is not None and grain < 1000) else ('grain_known' if grain is not None else ('microstructure_text_only' if re.search(r'grain|sem|tem|crystallite|defect|porosity', text) else 'unknown'))
        rd.update({'temperature_K_v40': temp, 'kappa_W_mK_v40': kap, 'grain_size_nm_v40': grain, 'microstructure_class_v40': micro, 'usable_kappa_microstructure_v40': bool(temp and kap and micro != 'unknown')})
        rows.append(rd)
    _v38_write_rows(rows, f'{test_id.lower()}_microstructure_kappa_normalized_rows_v40.csv')
    usable = [r for r in rows if r.get('usable_kappa_microstructure_v40')]
    model: Dict[str, Any] = {'status': 'insufficient_normalized_kappa_microstructure_rows', 'n_rows': len(usable)}
    strict = False
    if len(usable) >= 12:
        t = np.array([float(r['temperature_K_v40']) for r in usable], dtype=float)
        k = np.array([float(r['kappa_W_mK_v40']) for r in usable], dtype=float)
        good = np.isfinite(t) & np.isfinite(k) & (t > 0) & (k > 0)
        if int(good.sum()) >= 8:
            lx = np.log(t[good]); ly = np.log(k[good])
            free = _v37_ols_fit(ly, np.column_stack([np.ones(len(lx)), lx]))
            alpha = (free.get('beta') or [None, None])[1] if free.get('ok') else None
            model = {'status': 'loglog_kappa_model_run', 'n_rows': int(good.sum()), 'free_alpha': alpha, 'fit': free, 'fixed_alpha_target': 0.5}
            strict = bool(int(good.sum()) >= 20 and alpha is not None and 0.25 <= float(alpha) <= 0.85)
    failed = [] if strict else ['temperature_K/kappa_W_mK_normalization', 'N>=20_usable_rows', 'source_material_temperature_jackknife']
    return {'priority': 3, 'status': 'microstructure_kappa_strict_pass' if strict else 'microstructure_kappa_normalized_not_strict', 'rows_artifact': f'data/generated/{test_id.lower()}_microstructure_kappa_normalized_rows_v40.csv', 'rows_written': len(rows), 'usable_rows': len(usable), 'model': model, 'failed_subgates': failed, 'strict_confirm_ready': strict}


def _v40_t53_structure_real(args) -> Dict[str, Any]:
    df = _v40_read_any_csv(['t53_symmetry_contact_model_rows_v39.csv', 't53_symmetry_contact_model_rows_v38.csv', 't53_proteingym_enriched_rows_v32.csv', 't53_proteingym_enriched_rows_v30.csv'])
    rows: List[Dict[str, Any]] = []
    for _, r in df.iterrows():
        rd = dict(r)
        text = _v40_text_of_row(rd)
        sym = _v40_norm_float(rd.get('symmetry_order_v39') or rd.get('symmetry_order') or rd.get('bioassembly_symmetry_order'))
        olig = str(rd.get('oligomeric_state_v39') or rd.get('oligomeric_state') or '')
        contact = _v40_norm_float(rd.get('contact_network_regularity_v39') or rd.get('contact_network_regularity') or rd.get('contact_regularity'))
        if sym is None:
            if re.search(r'\bhomo[- ]?dimer\b|C2|dimer', text, re.I): sym = 2.0; olig = olig or 'dimer'
            elif re.search(r'trimer|C3', text, re.I): sym = 3.0; olig = olig or 'trimer'
            elif re.search(r'tetramer|C4|D2', text, re.I): sym = 4.0; olig = olig or 'tetramer'
            else: sym = 1.0
        if contact is None:
            contact = min(1.0, math.log1p(max(sym or 1.0, 1.0)) / math.log(8.0))
        score = float(sym or 0.0) * float(contact or 0.0)
        rd.update({'symmetry_order_v40': sym, 'oligomeric_state_v40': olig or ('monomer' if sym == 1 else 'unknown'), 'contact_network_regularity_v40': contact, 'ccdr_symmetry_contact_proxy_v40': score, 'has_real_structure_proxy_v40': bool(sym is not None and contact is not None)})
        rows.append(rd)
    _v38_write_rows(rows, 't53_real_structure_contact_rows_v40.csv')
    usable = [r for r in rows if r.get('has_real_structure_proxy_v40')]
    # Without outcome DMS-score columns this remains near-confirm only.
    outcome_cols = [c for c in (df.columns if not df.empty else []) if re.search(r'dms|fitness|score|effect', str(c), re.I)]
    model = {'status': 'structure_proxy_rows_available_outcome_needed', 'n_rows': len(usable), 'candidate_outcome_columns': [str(c) for c in outcome_cols[:10]]}
    strict = False
    return {'priority': 4, 'status': 't53_real_structure_proxy_rows_written', 'n_rows': len(rows), 'usable_structure_proxy_rows': len(usable), 'rows_artifact': 'data/generated/t53_real_structure_contact_rows_v40.csv', 'model': model, 'strict_confirm_ready': strict, 'failed_subgates': ['DMS_outcome_join', 'family_assay_sequence_jackknife', 'bootstrap_CI_or_BH_FDR']}


def _v40_t34_thermo_header(args) -> Dict[str, Any]:
    df = _v40_read_any_csv(['t34_bi2te3_zt_angle_rows_v39.csv', 't34_bi2te3_zt_angle_rows_v38.csv', 't34_bi2te3_zt_angle_rows_v37.csv'])
    rows: List[Dict[str, Any]] = []
    for _, r in df.iterrows():
        rd = dict(r)
        text = _v40_text_of_row(rd)
        mat = str(rd.get('material_v39') or rd.get('material') or rd.get('composition') or '')
        if not mat:
            m = re.search(r'(Bi\s*2\s*Te\s*3|Sb\s*2\s*Te\s*3|Bi2Te3|Sb2Te3|BiSbTe)', text, re.I)
            mat = m.group(1) if m else ''
        zt = _v40_norm_float(rd.get('ZT_v39') or rd.get('ZT') or rd.get('zT') or rd.get('zt'))
        temp = _v40_norm_float(rd.get('temperature_K_v39') or rd.get('temperature_K') or rd.get('temperature') or rd.get('T'))
        angle = _v40_norm_float(rd.get('orientation_or_grain_angle_deg_v39') or rd.get('orientation_angle_deg') or rd.get('grain_boundary_angle_deg') or rd.get('angle'))
        if angle is None:
            m = re.search(r'(?:angle|orientation|grain boundary|theta|θ)[^\d]{0,20}(\d+(?:\.\d+)?)', text, re.I)
            if m: angle = float(m.group(1))
        if zt is None:
            m = re.search(r'\bZT\b[^\d]{0,20}(\d+(?:\.\d+)?)', text, re.I)
            if m: zt = float(m.group(1))
        rd.update({'material_v40': mat, 'ZT_v40': zt, 'temperature_K_v40': temp, 'orientation_or_grain_angle_deg_v40': angle, 'thermo_confirm_eligible_v40': bool(mat and zt is not None and angle is not None and re.search(r'Bi|Sb|Te', mat, re.I))})
        rows.append(rd)
    _v38_write_rows(rows, 't34_bi2te3_zt_angle_rows_v40.csv')
    usable = [r for r in rows if r.get('thermo_confirm_eligible_v40')]
    model = {'status': 'insufficient_orientation_zt_rows', 'n_rows': len(usable)}
    strict = False
    if len(usable) >= 12:
        y = np.array([float(r['ZT_v40']) for r in usable], dtype=float)
        a = np.array([float(r['orientation_or_grain_angle_deg_v40']) for r in usable], dtype=float)
        fit = _v37_ols_fit(y, np.column_stack([np.ones(len(y)), np.cos(np.deg2rad(6*a))]))
        model = {'status': 'cos6_orientation_model_run', 'n_rows': len(usable), 'fit': fit, 'cos6_coef': (fit.get('beta') or [None, None])[1] if fit.get('ok') else None}
        strict = bool(len(usable) >= 20 and fit.get('ok'))
    return {'priority': 5, 'status': 't34_thermo_header_mapping_not_strict' if not strict else 't34_thermo_header_mapping_strict_pass', 'rows_artifact': 'data/generated/t34_bi2te3_zt_angle_rows_v40.csv', 'rows_written': len(rows), 'usable_angle_zt_rows': len(usable), 'model': model, 'strict_confirm_ready': strict, 'failed_subgates': [] if strict else ['>=20_Bi2Te3/Sb2Te3_orientation_ZT_rows', 'cos6_model', 'source_material_jackknife']}


def _v40_exact_hepdata_registry(args, test_id: str) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    for fn in ['exact_hepdata_registry_v39.csv', 'exact_hepdata_registry_v38.csv', 'exact_hepdata_registry_v37.csv', 'exact_hepdata_manifest_v30.csv', 'exact_hepdata_manifest.csv']:
        df = _v38_safe_read_csv(DATA_DIR / fn)
        if df.empty:
            df = _v38_safe_read_csv(DATA_DIR / 'generated' / fn)
        if df.empty:
            continue
        for _, r in df.iterrows():
            rd = dict(r)
            if str(rd.get('test_id') or '').upper() in {'', test_id} or str(rd.get('prediction_id') or '').upper() in {'P9B','P9E','P9F'}:
                rd['registry_source_v40'] = fn
                rows.append(rd)
    if not rows:
        rows = [{'test_id': test_id, 'prediction_id': 'P9b/P9e/P9f' if test_id == 'T59' else 'cosmic_ray_cross_section', 'record_id': '', 'table_id': '', 'x_column': '', 'y_column': '', 'err_column': '', 'observable': '', 'experiment': '', 'status': 'needs_exact_manual_registry_entry_from_public_HEPData'}]
    _v38_write_rows(rows, f'{test_id.lower()}_exact_hepdata_registry_v40.csv')
    complete = [r for r in rows if r.get('record_id') and r.get('table_id') and r.get('y_column')]
    return {'priority': 6, 'status': 'hepdata_registry_ready_to_fetch' if complete else 'hepdata_registry_scaffold_needs_exact_entries', 'registry_artifact': f'data/generated/{test_id.lower()}_exact_hepdata_registry_v40.csv', 'registry_rows': len(rows), 'complete_registry_rows': len(complete), 'strict_confirm_ready': False, 'failed_subgates': ['complete_record_table_column_registry', 'parse_official_YAML_JSON', 'observed_expected_error_model']}


def _v40_t45_t47_exact(args, test_id: str) -> Dict[str, Any]:
    files = ['t45_optical_interconnect_rows_v29.csv','t45_optical_interconnect_rows_v28.csv','t45_optical_interconnect_rows_v27.csv'] if test_id == 'T45' else ['t47_neuromorphic_rows_v29.csv','t47_neuromorphic_rows_v28.csv','t47_neuromorphic_rows_v27.csv']
    df = _v40_read_any_csv(files)
    rows = []
    for _, r in df.iterrows():
        rd = dict(r)
        text = _v40_text_of_row(rd)
        if test_id == 'T45':
            energy = _v40_norm_float(rd.get('fJ_per_bit') or rd.get('pJ_per_bit') or rd.get('energy_per_bit'))
            bw = _v40_norm_float(rd.get('bandwidth_Gbps') or rd.get('Gbps') or rd.get('bandwidth'))
            reach = _v40_norm_float(rd.get('reach_mm') or rd.get('reach_m') or rd.get('distance'))
            if energy is None:
                m = re.search(r'(\d+(?:\.\d+)?)\s*(fJ|pJ)\s*/?\s*bit', text, re.I)
                if m: energy = float(m.group(1)) * (1000.0 if m.group(2).lower() == 'pj' else 1.0)
            rd.update({'energy_fJ_per_bit_v40': energy, 'bandwidth_Gbps_v40': bw, 'reach_value_v40': reach, 'exact_benchmark_row_v40': bool(energy is not None and bw is not None)})
        else:
            energy = _v40_norm_float(rd.get('energy_per_inference') or rd.get('energy_mJ') or rd.get('energy_uJ') or rd.get('energy'))
            acc = _v40_norm_float(rd.get('accuracy') or rd.get('acc'))
            chip = str(rd.get('chip') or rd.get('platform') or '')
            if not chip:
                m = re.search(r'(Loihi\s*2?|TrueNorth|SpiNNaker|BrainScaleS)', text, re.I)
                chip = m.group(1) if m else ''
            rd.update({'chip_v40': chip, 'energy_per_inference_v40': energy, 'accuracy_v40': acc, 'exact_benchmark_row_v40': bool(chip and energy is not None)})
        rows.append(rd)
    _v38_write_rows(rows, f'{test_id.lower()}_exact_benchmark_rows_v40.csv')
    exact = [r for r in rows if r.get('exact_benchmark_row_v40')]
    return {'priority': 7, 'status': f'{test_id.lower()}_exact_rows_found' if exact else f'{test_id.lower()}_exact_rows_missing', 'rows_artifact': f'data/generated/{test_id.lower()}_exact_benchmark_rows_v40.csv', 'rows_written': len(rows), 'exact_rows': len(exact), 'strict_confirm_ready': False, 'failed_subgates': ['exact_public_benchmark_rows', 'baseline_model', 'jackknife']}


