    # v40 policy artifact: metadata wrappers are counted as rejected, never as table candidates.
    return {'priority': 9, 'status': 'fusion_exact_file_only_low_priority', 'strict_confirm_ready': False, 'metadata_wrappers_rejected': True, 'accepted_extensions': ['.csv','.tsv','.xlsx','.xls','.dat','.txt','.sav','.mat','.h5','.hdf5','.nc'], 'required_next': 'exact public measurement attachment with shot/device and physical variables', 'failed_subgates': ['no_exact_public_measurement_attachment']}


