    failed += ['cos6theta_model','source_material_jackknife']
    return {'priority':4,'status':'t34_angle_zt_rows_ready_v48' if usable>=20 else 't34_angle_zt_rows_underpowered_v48','rows_artifact':'data/generated/t34_bi2te3_zt_angle_rows_v48.csv','usable_angle_zt_rows':usable,'rows_written':len(rows),'strict_confirm_ready':False,'failed_subgates':failed,'base_v47':base}


