def _v48_benchmark(args, test_id: str) -> Dict[str, Any]:
    base={}
    try: base=_v47_benchmark(args,test_id)
    except Exception as e: base={'status':f'v47_base_unavailable: {type(e).__name__}: {e}'}
    df=_v48_read_many([f'{test_id.lower()}_exact_benchmark_rows_v47.csv',f'{test_id.lower()}_exact_benchmark_rows_v46.csv'])
    rows=[]; exact=0
    for _,r in df.iterrows():
        rd=dict(r); text=_v48_text(rd)
        if test_id=='T45':
            energy=_v47_find_value(rd,[r'fJ.*bit',r'pJ.*bit',r'energy.*bit'])
            bw=_v47_find_value(rd,[r'bandwidth',r'Gb/s',r'Gbps'])
            reach=_v47_find_value(rd,[r'reach',r'distance',r'mm',r'km'])
            ok=energy is not None and bw is not None and reach is not None
            rd.update({'energy_per_bit_v48':energy,'bandwidth_v48':bw,'reach_v48':reach,'exact_benchmark_row_v48':ok})
        else:
            chip=str(_v48_find_alias(rd,[r'chip',r'platform',r'loihi',r'truenorth',r'spinnaker',r'brainscales']) or '')
            energy=_v47_find_value(rd,[r'energy.*inference',r'joule',r'mJ',r'uJ'])
            acc=_v47_find_value(rd,[r'accuracy',r'top.*1',r'error'])
            ok=bool(chip and energy is not None and acc is not None)
            rd.update({'chip_platform_v48':chip,'energy_per_inference_v48':energy,'accuracy_v48':acc,'exact_benchmark_row_v48':ok})
        if ok: exact+=1
        rows.append(rd)
    if not rows:
        rows=[{'test_id':test_id,'exact_benchmark_row_v48':False,'required_v48':'T45 energy/bit+bandwidth+reach OR T47 chip+energy/inference+accuracy'}]
    _v38_write_rows(rows,f'{test_id.lower()}_exact_benchmark_rows_v48.csv')
    return {'priority':6 if test_id=='T45' else 7,'status':'exact_benchmark_rows_available_v48' if exact else 'exact_benchmark_rows_missing_v48','rows_artifact':f'data/generated/{test_id.lower()}_exact_benchmark_rows_v48.csv','rows_written':len(rows),'exact_rows':exact,'strict_confirm_ready':False,'failed_subgates':['>=20_exact_rows','controlled_model_and_jackknife'],'base_v47':base}


