    rows=[]; complete=0
    for _, rr in df.iterrows():
        rd=dict(rr)
        has=all(_v47_nonempty(_v49_alias(rd,[pat])) for pat in [r'record',r'table',r'x_?column|xcol|mass',r'y_?column|ycol|observed|limit|cross',r'err|uncert|sigma|error'])
        complete+=int(has); rd.update({'complete_registry_row_v49':has,'official_fetch_order_v49':'record_json -> submission_yaml/original -> table_yaml -> table_csv'})
