    _v51_write(rows,'t44_tier_a_source_audit_rows_v51.csv')
    _v51_write(tier_a,'t44_true_tier_a_rows_v51.csv')
    _v51_write(recovery,'t44_tier_a_recovery_candidates_v51.csv')
    return {'priority':3,'status':'frozen_strict_confirmed_true_tier_a_audit_v51','rows_artifact':'data/generated/t44_tier_a_source_audit_rows_v51.csv','true_tier_a_artifact':'data/generated/t44_true_tier_a_rows_v51.csv','recovery_artifact':'data/generated/t44_tier_a_recovery_candidates_v51.csv','rows_written':len(rows),'true_tier_a_rows':len(tier_a),'tier_a_recovery_candidates':len(recovery),'strict_confirm_ready':True,'gate_policy':'frozen T44 confirm; Tier-A audit only','base_v50':base}


