def _v51_t53(args) -> Dict[str, Any]:
    base={}
    try: base=_v50_t53(args)
    except Exception as e: base={'status':f'v50_base_unavailable: {type(e).__name__}: {e}'}
    df=_v51_read_many(['t53_final_structure_dms_model_rows_v50.csv','t53_final_structure_dms_model_rows_v49.csv','t53_proteingym_enriched_rows_v32.csv'])
    rows=[]
    for _,rr in df.iterrows():
        rd=dict(rr)
        outcome=_v50_float(rd.get('dms_outcome_v50') or rd.get('dms_outcome_v49') or _v47_find_value(rd,[r'fitness',r'effect',r'score',r'dms']))
        proxy=_v50_float(rd.get('structure_contact_proxy_v50') or rd.get('structure_contact_proxy_v49') or rd.get('ccdr_symmetry_contact_proxy_v43'))
        join_key=str(rd.get('uniprot_id') or rd.get('uniprot') or rd.get('target') or rd.get('protein') or '')
