    return {'priority':5,'status':'t53_real_join_manifest_pending_model_v51','rows_artifact':'data/generated/t53_real_dms_structure_join_rows_v51.csv','summary_artifact':'data/generated/t53_real_dms_structure_join_summary_v51.csv','model_usable_rows':len(usable),'strict_confirm_ready':False,'failed_subgates':failed,'base_v50':base}


