# -----------------------------------------------------------------------------
# v65: keep default T44 runs lightweight.
#
# The legacy T44 wrapper chain re-reads and rewrites historical generated NAND
# CSVs for robustness/audit layers. That is expensive and not needed for the
# current public-claim policy, where T44 remains blocked until exact source-pack
# rows exist. Keep the old path available only when explicitly requested.
# -----------------------------------------------------------------------------
_T44_LEGACY_RUNNER_V65 = SPECIAL_RUNNERS.get("T44")


def _t44_fast_exact_source_required_v65(args) -> Dict[str, Any]:
    if getattr(args, "allow_broad_discovery", False) and _T44_LEGACY_RUNNER_V65 is not None:
        return _T44_LEGACY_RUNNER_V65(args)
    obj = run_t44(args)
    confirmation = "not_confirmed_audit_repair_required"
    blocker = "true_tier_a_nand_rows_required"
    next_source = "data/exact_sources/nand rows with company/year/layers/capacity_Gb/die_area_mm2/bits_per_cell/source_url"
    split = {
        "execution_status_v59": "ok",
        "data_status_v59": "true_tier_a_nand_rows_required",
        "evidence_status_v59": "audit_repair_route",
        "confirmation_status_v59": confirmation,
    }
    target = {
        "schema": "ccdr-tierb-confirm-target-v65-fast-t44",
        "test_id": "T44",
        "rank_score_0_10_v59": 8,
        "blocker_type_v59": blocker,
        "next_data_source_v59": next_source,
        "expected_effort_v59": "medium",
        "confirmation_legally_possible_v59": True,
        "confirmation_status_v59": confirmation,
    }
    obj.update({
        "schema": "ccdr-tierb-result-v65-fast-t44",
        "auto_data_improvements_v59": {
            "t44_fast_exact_source_gate_v65": {
                "status": "exact_nand_source_pack_required",
                "strict_confirm_ready_v65": False,
                "legacy_robustness_stack_skipped_v65": True,
                "enable_legacy_stack_with": "--allow-broad-discovery",
            }
        },
        "status_split_v59": split,
        "confirm_target_v59": target,
        "confirm_allowed_now_v59": False,
        "confirmation_label_v59": confirmation,
        "confirmation_blocker_v59": {
            "strict_confirm_allowed_now": False,
            "public_confirm_allowed_now": False,
            "why_not_confirmed": blocker,
            "single_next_blocker": blocker,
            "best_auto_data_source_next": next_source,
        },
        "near_confirm_score_v59": {
            "score_0_10": 8,
            "primary_table_available": False,
            "model_rows_available": False,
            "model_gate_attempted": False,
            "strict_gate_remaining": [blocker],
        },
        "public_claim_gate_v59": {
            "claimable_only_if_listed_in": "positive_dashboard.json:v59_confirm_status.confirmed_now",
            "confirmed_now_v59": False,
            "legacy_confirm_fields_are_not_public_claims": True,
        },
        "positive_dashboard_fragment_v59": {
            "test_id": "T44",
            "verdict": obj.get("programmatic_verdict") or obj.get("status"),
            "confirmation_label": confirmation,
            "confirm_allowed_now": False,
            "strict_confirm_allowed_now": False,
            "near_confirm_score": {"score_0_10": 8, "strict_gate_remaining": [blocker]},
            "status_split_v59": split,
            "why_not_confirmed": blocker,
            "single_next_blocker": blocker,
            "best_auto_data_source_next": next_source,
            "confirm_target_v59": target,
        },
    })
    obj.update(split)
    obj["quality_patch_version"] = str(obj.get("quality_patch_version", "")) + "+v65_fast_t44"
    return obj


SPECIAL_RUNNERS["T44"] = _t44_fast_exact_source_required_v65
